window.TXB=window.TXB||{};TXB["svd/Exo"]={"1:1":"وهذه أسماء بني إسرائيل الذين جاءوا إلى مصر. مع يعقوب جاء كل إنسان وبيته:","1:2":"رأوبين وشمعون ولاوي ويهوذا","1:3":"ويساكر وزبولون وبنيامين","1:4":"ودان ونفتالي وجاد وأشير.","1:5":"وكانت جميع نفوس الخارجين من صلب يعقوب سبعين نفسا. ولكن يوسف كان في مصر.","1:6":"ومات يوسف وكل إخوته وجميع ذلك الجيل.","1:7":"وأما بنو إسرائيل فأثمروا وتوالدوا ونموا وكثروا كثيرا جدا, وامتلأت الأرض منهم.","1:8":"ثم قام ملك جديد على مصر لم يكن يعرف يوسف.","1:9":"فقال لشعبه: «هوذا بنو إسرائيل شعب أكثر وأعظم منا.","1:10":"هلم نحتال لهم لئلا ينموا, فيكون إذا حدثت حرب أنهم ينضمون إلى أعدائنا ويحاربوننا ويصعدون من الأرض».","1:11":"فجعلوا عليهم رؤساء تسخير لكي يذلوهم بأثقالهم, فبنوا لفرعون مدينتي مخازن: فيثوم, ورعمسيس.","1:12":"ولكن بحسبما أذلوهم هكذا نموا وامتدوا. فاختشوا من بني إسرائيل.","1:13":"فاستعبد المصريون بني إسرائيل بعنف,","1:14":"ومرروا حياتهم بعبودية قاسية في الطين واللبن وفي كل عمل في الحقل. كل عملهم الذي عملوه بواسطتهم عنفا.","1:15":"وكلم ملك مصر قابلتي العبرانيات اللتين اسم إحداهما شفرة واسم الأخرى فوعة,","1:16":"وقال: «حينما تولدان العبرانيات وتنظرانهن على الكراسي, إن كان ابنا فاقتلاه, وإن كان بنتا فتحيا».","1:17":"ولكن القابلتين خافتا الله ولم تفعلا كما كلمهما ملك مصر, بل استحيتا الأولاد.","1:18":"فدعا ملك مصر القابلتين وقال لهما: «لماذا فعلتما هذا الأمر واستحييتما الأولاد؟»","1:19":"فقالت القابلتان لفرعون: «إن النساء العبرانيات لسن كالمصريات, فإنهن قويات يلدن قبل أن تأتيهن القابلة».","1:20":"فأحسن الله إلى القابلتين, ونما الشعب وكثر جدا.","1:21":"وكان إذ خافت القابلتان الله أنه صنع لهما بيوتا.","1:22":"ثم أمر فرعون جميع شعبه قائلا: «كل ابن يولد تطرحونه في النهر, لكن كل بنت تستحيونها».","2:1":"وذهب رجل من بيت لاوي وأخذ بنت لاوي,","2:2":"فحبلت المرأة وولدت ابنا. ولما رأته أنه حسن, خبأته ثلاثة أشهر.","2:3":"ولما لم يمكنها أن تخبئه بعد, أخذت له سفطا من البردي وطلته بالحمر والزفت, ووضعت الولد فيه, ووضعته بين الحلفاء على حافة النهر.","2:4":"ووقفت أخته من بعيد لتعرف ماذا يفعل به.","2:5":"فنزلت ابنة فرعون إلى النهر لتغتسل, وكانت جواريها ماشيات على جانب النهر. فرأت السفط بين الحلفاء, فأرسلت أمتها وأخذته.","2:6":"ولما فتحته رأت الولد, وإذا هو صبي يبكي. فرقت له وقالت: «هذا من أولاد العبرانيين».","2:7":"فقالت أخته لابنة فرعون: «هل أذهب وأدعو لك امرأة مرضعة من العبرانيات لترضع لك الولد؟»","2:8":"فقالت لها ابنة فرعون: «اذهبي». فذهبت الفتاة ودعت أم الولد.","2:9":"فقالت لها ابنة فرعون: «اذهبي بهذا الولد وأرضعيه لي وأنا أعطي أجرتك». فأخذت المرأة الولد وأرضعته.","2:10":"ولما كبر الولد جاءت به إلى ابنة فرعون فصار لها ابنا, ودعت اسمه «موسى» وقالت: «إني انتشلته من الماء».","2:11":"وحدث في تلك الأيام لما كبر موسى أنه خرج إلى إخوته لينظر في أثقالهم, فرأى رجلا مصريا يضرب رجلا عبرانيا من إخوته,","2:12":"فالتفت إلى هنا وهناك ورأى أن ليس أحد, فقتل المصري وطمره في الرمل.","2:13":"ثم خرج في اليوم الثاني وإذا رجلان عبرانيان يتخاصمان, فقال للمذنب: «لماذا تضرب صاحبك؟»","2:14":"فقال: «من جعلك رئيسا وقاضيا علينا؟ أمفتكر أنت بقتلي كما قتلت المصري؟». فخاف موسى وقال: «حقا قد عرف الأمر».","2:15":"فسمع فرعون هذا الأمر, فطلب أن يقتل موسى. فهرب موسى من وجه فرعون وسكن في أرض مديان, وجلس عند البئر.","2:16":"وكان لكاهن مديان سبع بنات, فأتين واستقين وملأن الأجران ليسقين غنم أبيهن.","2:17":"فأتى الرعاة وطردوهن. فنهض موسى وأنجدهن وسقى غنمهن.","2:18":"فلما أتين إلى رعوئيل أبيهن قال: «ما بالكن أسرعتن في المجيء اليوم؟»","2:19":"فقلن: «رجل مصري أنقذنا من أيدي الرعاة, وإنه استقى لنا أيضا وسقى الغنم».","2:20":"فقال لبناته: «وأين هو؟ لماذا تركتن الرجل؟ ادعونه ليأكل طعاما».","2:21":"فارتضى موسى أن يسكن مع الرجل, فأعطى موسى صفورة ابنته.","2:22":"فولدت ابنا فدعا اسمه «جرشوم», لأنه قال: «كنت نزيلا في أرض غريبة».","2:23":"وحدث في تلك الأيام الكثيرة أن ملك مصر مات. وتنهد بنو إسرائيل من العبودية وصرخوا, فصعد صراخهم إلى الله من أجل العبودية.","2:24":"فسمع الله أنينهم, فتذكر الله ميثاقه مع إبراهيم وإسحاق ويعقوب.","2:25":"ونظر الله بني إسرائيل وعلم الله.","3:1":"وأما موسى فكان يرعى غنم يثرون حميه كاهن مديان, فساق الغنم إلى وراء البرية وجاء إلى جبل الله حوريب.","3:2":"وظهر له ملاك الرب بلهيب نار من وسط عليقة. فنظر وإذا العليقة تتوقد بالنار, والعليقة لم تكن تحترق.","3:3":"فقال موسى: «أميل الآن لأنظر هذا المنظر العظيم. لماذا لا تحترق العليقة؟».","3:4":"فلما رأى الرب أنه مال لينظر, ناداه الله من وسط العليقة وقال: «موسى, موسى!». فقال: «هأنذا».","3:5":"فقال: «لا تقترب إلى ههنا. اخلع حذاءك من رجليك, لأن الموضع الذي أنت واقف عليه أرض مقدسة».","3:6":"ثم قال: «أنا إله أبيك, إله إبراهيم وإله إسحاق وإله يعقوب». فغطى موسى وجهه لأنه خاف أن ينظر إلى الله.","3:7":"فقال الرب: «إني قد رأيت مذلة شعبي الذي في مصر وسمعت صراخهم من أجل مسخريهم. إني علمت أوجاعهم,","3:8":"فنزلت لأنقذهم من أيدي المصريين, وأصعدهم من تلك الأرض إلى أرض جيدة وواسعة, إلى أرض تفيض لبنا وعسلا, إلى مكان الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين.","3:9":"والآن هوذا صراخ بني إسرائيل قد أتى إلي, ورأيت أيضا الضيقة التي يضايقهم بها المصريون,","3:10":"فالآن هلم فأرسلك إلى فرعون, وتخرج شعبي بني إسرائيل من مصر».","3:11":"فقال موسى لله: «من أنا حتى أذهب إلى فرعون, وحتى أخرج بني إسرائيل من مصر؟»","3:12":"فقال: «إني أكون معك, وهذه تكون لك العلامة أني أرسلتك: حينما تخرج الشعب من مصر, تعبدون الله على هذا الجبل».","3:13":"فقال موسى لله: «ها أنا آتي إلى بني إسرائيل وأقول لهم: إله آبائكم أرسلني إليكم. فإذا قالوا لي: ما اسمه؟ فماذا أقول لهم؟»","3:14":"فقال الله لموسى: «أهيه الذي أهيه». وقال: «هكذا تقول لبني إسرائيل: أهيه أرسلني إليكم».","3:15":"وقال الله أيضا لموسى: «هكذا تقول لبني إسرائيل: يهوه إله آبائكم, إله إبراهيم وإله إسحاق وإله يعقوب أرسلني إليكم. هذا اسمي إلى الأبد وهذا ذكري إلى دور فدور.","3:16":"اذهب واجمع شيوخ إسرائيل وقل لهم: الرب إله آبائكم, إله إبراهيم وإسحاق ويعقوب ظهر لي قائلا: إني قد افتقدتكم وما صنع بكم في مصر.","3:17":"فقلت أصعدكم من مذلة مصر إلى أرض الكنعانيين والحثيين والأموريين والفرزيين والحويين واليبوسيين, إلى أرض تفيض لبنا وعسلا.","3:18":"«فإذا سمعوا لقولك, تدخل أنت وشيوخ بني إسرائيل إلى ملك مصر وتقولون له: الرب إله العبرانيين التقانا, فالآن نمضي سفر ثلاثة أيام في البرية ونذبح للرب إلهنا.","3:19":"ولكني أعلم أن ملك مصر لا يدعكم تمضون ولا بيد قوية,","3:20":"فأمد يدي وأضرب مصر بكل عجائبي التي أصنع فيها. وبعد ذلك يطلقكم.","3:21":"وأعطي نعمة لهذا الشعب في عيون المصريين. فيكون حينما تمضون أنكم لا تمضون فارغين.","3:22":"بل تطلب كل امرأة من جارتها ومن نزيلة بيتها أمتعة فضة وأمتعة ذهب وثيابا, وتضعونها على بنيكم وبناتكم. فتسلبون المصريين».","4:1":"فأجاب موسى وقال: «ولكن ها هم لا يصدقونني ولا يسمعون لقولي, بل يقولون: لم يظهر لك الرب».","4:2":"فقال له الرب: «ما هذه في يدك؟» فقال: «عصا».","4:3":"فقال: «اطرحها إلى الأرض». فطرحها إلى الأرض فصارت حية, فهرب موسى منها.","4:4":"ثم قال الرب لموسى: «مد يدك وأمسك بذنبها». فمد يده وأمسك به, فصارت عصا في يده.","4:5":"«لكي يصدقوا أنه قد ظهر لك الرب إله آبائهم, إله إبراهيم وإله إسحاق وإله يعقوب».","4:6":"ثم قال له الرب أيضا: «أدخل يدك في عبك». فأدخل يده في عبه ثم أخرجها, وإذا يده برصاء مثل الثلج.","4:7":"ثم قال له: «رد يدك إلى عبك». فرد يده إلى عبه ثم أخرجها من عبه, وإذا هي قد عادت مثل جسده.","4:8":"«فيكون إذا لم يصدقوك ولم يسمعوا لصوت الآية الأولى, أنهم يصدقون صوت الآية الأخيرة.","4:9":"ويكون إذا لم يصدقوا هاتين الآيتين, ولم يسمعوا لقولك, أنك تأخذ من ماء النهر وتسكب على اليابسة, فيصير الماء الذي تأخذه من النهر دما على اليابسة».","4:10":"فقال موسى للرب: «استمع أيها السيد, لست أنا صاحب كلام منذ أمس ولا أول من أمس, ولا من حين كلمت عبدك, بل أنا ثقيل الفم واللسان».","4:11":"فقال له الرب: «من صنع للإنسان فما؟ أو من يصنع أخرس أو أصم أو بصيرا أو أعمى؟ أما هو أنا الرب؟","4:12":"فالآن اذهب وأنا أكون مع فمك وأعلمك ما تتكلم به».","4:13":"فقال: «استمع أيها السيد, أرسل بيد من ترسل».","4:14":"فحمي غضب الرب على موسى وقال: «أليس هارون اللاوي أخاك؟ أنا أعلم أنه هو يتكلم, وأيضا ها هو خارج لاستقبالك. فحينما يراك يفرح بقلبه,","4:15":"فتكلمه وتضع الكلمات في فمه, وأنا أكون مع فمك ومع فمه, وأعلمكما ماذا تصنعان.","4:16":"وهو يكلم الشعب عنك. وهو يكون لك فما, وأنت تكون له إلها.","4:17":"وتأخذ في يدك هذه العصا التي تصنع بها الآيات».","4:18":"فمضى موسى ورجع إلى يثرون حميه وقال له: «أنا أذهب وأرجع إلى إخوتي الذين في مصر لأرى هل هم بعد أحياء». فقال يثرون لموسى: «اذهب بسلام».","4:19":"وقال الرب لموسى في مديان: «اذهب ارجع إلى مصر, لأنه قد مات جميع القوم الذين كانوا يطلبون نفسك».","4:20":"فأخذ موسى امرأته وبنيه وأركبهم على الحمير ورجع إلى أرض مصر. وأخذ موسى عصا الله في يده.","4:21":"وقال الرب لموسى: «عندما تذهب لترجع إلى مصر, انظر جميع العجائب التي جعلتها في يدك واصنعها قدام فرعون. ولكني أشدد قلبه حتى لا يطلق الشعب.","4:22":"فتقول لفرعون: هكذا يقول الرب: إسرائيل ابني البكر.","4:23":"فقلت لك: أطلق ابني ليعبدني, فأبيت أن تطلقه. ها أنا أقتل ابنك البكر».","4:24":"وحدث في الطريق في المنزل أن الرب التقاه وطلب أن يقتله.","4:25":"فأخذت صفورة صوانة وقطعت غرلة ابنها ومست رجليه. فقالت: «إنك عريس دم لي».","4:26":"فانفك عنه. حينئذ قالت: «عريس دم من أجل الختان».","4:27":"وقال الرب لهارون: «اذهب إلى البرية لاستقبال موسى». فذهب والتقاه في جبل الله وقبله.","4:28":"فأخبر موسى هارون بجميع كلام الرب الذي أرسله, وبكل الآيات التي أوصاه بها.","4:29":"ثم مضى موسى وهارون وجمعا جميع شيوخ بني إسرائيل.","4:30":"فتكلم هارون بجميع الكلام الذي كلم الرب موسى به, وصنع الآيات أمام عيون الشعب.","4:31":"فآمن الشعب. ولما سمعوا أن الرب افتقد بني إسرائيل وأنه نظر مذلتهم, خروا وسجدوا.","5:1":"وبعد ذلك دخل موسى وهارون وقالا لفرعون: «هكذا يقول الرب إله إسرائيل: أطلق شعبي ليعيدوا لي في البرية».","5:2":"فقال فرعون: «من هو الرب حتى أسمع لقوله فأطلق إسرائيل؟ لا أعرف الرب, وإسرائيل لا أطلقه».","5:3":"فقالا: «إله العبرانيين قد التقانا, فنذهب سفر ثلاثة أيام في البرية ونذبح للرب إلهنا, لئلا يصيبنا بالوبإ أو بالسيف».","5:4":"فقال لهما ملك مصر: «لماذا يا موسى وهارون تبطلان الشعب من أعماله؟ اذهبا إلى أثقالكما».","5:5":"وقال فرعون: «هوذا الآن شعب الأرض كثير وأنتما تريحانهم من أثقالهم».","5:6":"فأمر فرعون في ذلك اليوم مسخري الشعب ومدبريه قائلا:","5:7":"«لا تعودوا تعطون الشعب تبنا لصنع اللبن كأمس وأول من أمس. ليذهبوا هم ويجمعوا تبنا لأنفسهم.","5:8":"ومقدار اللبن الذي كانوا يصنعونه أمس, وأول من أمس تجعلون عليهم. لا تنقصوا منه, فإنهم متكاسلون, لذلك يصرخون قائلين: نذهب ونذبح لإلهنا.","5:9":"ليثقل العمل على القوم حتى يشتغلوا به ولا يلتفتوا إلى كلام الكذب».","5:10":"فخرج مسخرو الشعب ومدبروه وكلموا الشعب, قائلين للشعب: «هكذا يقول فرعون: لست أعطيكم تبنا.","5:11":"اذهبوا أنتم وخذوا لأنفسكم تبنا من حيث تجدون. إنه لا ينقص من عملكم شيء».","5:12":"فتفرق الشعب في كل أرض مصر ليجمعوا قشا عوضا عن التبن.","5:13":"وكان المسخرون يعجلونهم قائلين: «كملوا أعمالكم, أمر كل يوم بيومه, كما كان حينما كان التبن».","5:14":"فضرب مدبرو بني إسرائيل الذين أقامهم عليهم مسخرو فرعون, وقيل لهم: «لماذا لم تكملوا فريضتكم من صنع اللبن أمس واليوم كالأمس وأول من أمس؟».","5:15":"فأتى مدبرو بني إسرائيل وصرخوا إلى فرعون قائلين: «لماذا تفعل هكذا بعبيدك؟","5:16":"التبن ليس يعطى لعبيدك, واللبن يقولون لنا: اصنعوه! وهوذا عبيدك مضروبون, وقد أخطأ شعبك».","5:17":"فقال: «متكاسلون أنتم, متكاسلون! لذلك تقولون: نذهب ونذبح للرب.","5:18":"فالآن اذهبوا اعملوا. وتبن لا يعطى لكم ومقدار اللبن تقدمونه».","5:19":"فرأى مدبرو بني إسرائيل أنفسهم في بلية إذ قيل لهم لا تنقصوا من لبنكم أمر كل يوم بيومه.","5:20":"وصادفوا موسى وهارون واقفين للقائهم حين خرجوا من لدن فرعون.","5:21":"فقالوا لهما: «ينظر الرب إليكما ويقضي, لأنكما أنتنتما رائحتنا في عيني فرعون وفي عيون عبيده حتى تعطيا سيفا في أيديهم ليقتلونا».","5:22":"فرجع موسى إلى الرب وقال: «يا سيد, لماذا أسأت إلى هذا الشعب؟ لماذا أرسلتني؟","5:23":"فإنه منذ دخلت إلى فرعون لأتكلم باسمك, أساء إلى هذا الشعب. وأنت لم تخلص شعبك».","6:1":"فقال الرب لموسى: «الآن تنظر ما أنا أفعل بفرعون. فإنه بيد قوية يطلقهم, وبيد قوية يطردهم من أرضه».","6:2":"ثم كلم الله موسى وقال له: «أنا الرب.","6:3":"وأنا ظهرت لإبراهيم وإسحاق ويعقوب بأني الإله القادر على كل شيء. وأما باسمي «يهوه» فلم أعرف عندهم.","6:4":"وأيضا أقمت معهم عهدي: أن أعطيهم أرض كنعان أرض غربتهم التي تغربوا فيها.","6:5":"وأنا أيضا قد سمعت أنين بني إسرائيل الذين يستعبدهم المصريون, وتذكرت عهدي.","6:6":"لذلك قل لبني إسرائيل: أنا الرب. وأنا أخرجكم من تحت أثقال المصريين وأنقذكم من عبوديتهم وأخلصكم بذراع ممدودة وبأحكام عظيمة,","6:7":"وأتخذكم لي شعبا, وأكون لكم إلها. فتعلمون أني أنا الرب إلهكم الذي يخرجكم من تحت أثقال المصريين.","6:8":"وأدخلكم إلى الأرض التي رفعت يدي أن أعطيها لإبراهيم وإسحاق ويعقوب. وأعطيكم إياها ميراثا. أنا الرب».","6:9":"فكلم موسى بني إسرائيل هكذا, ولكن لم يسمعوا لموسى من صغر النفس, ومن العبودية القاسية.","6:10":"ثم كلم الرب موسى قائلا:","6:11":"«ادخل قل لفرعون ملك مصر أن يطلق بني إسرائيل من أرضه».","6:12":"فتكلم موسى أمام الرب قائلا: «هوذا بنو إسرائيل لم يسمعوا لي, فكيف يسمعني فرعون وأنا أغلف الشفتين؟»","6:13":"فكلم الرب موسى وهارون, وأوصى معهما إلى بني إسرائيل وإلى فرعون ملك مصر في إخراج بني إسرائيل من أرض مصر.","6:14":"هؤلاء رؤساء بيوت آبائهم: بنو رأوبين بكر إسرائيل: حنوك وفلو وحصرون وكرمي. هذه عشائر رأوبين.","6:15":"وبنو شمعون: يموئيل ويامين وأوهد وياكين وصوحر وشأول ابن الكنعانية. هذه عشائر شمعون.","6:16":"وهذه أسماء بني لاوي بحسب مواليدهم: جرشون وقهات ومراري. وكانت سنو حياة لاوي مئة وسبعا وثلاثين سنة.","6:17":"ابنا جرشون: لبني وشمعي بحسب عشائرهما.","6:18":"وبنو قهات: عمرام ويصهار وحبرون وعزيئيل. وكانت سنو حياة قهات مئة وثلاثا وثلاثين سنة.","6:19":"وابنا مراري: محلي وموشي. هذه عشائر اللاويين بحسب مواليدهم.","6:20":"وأخذ عمرام يوكابد عمته زوجة له. فولدت له هارون وموسى. وكانت سنو حياة عمرام مئة وسبعا وثلاثين سنة.","6:21":"وبنو يصهار: قورح ونافج وذكري.","6:22":"وبنو عزيئيل: ميشائيل وألصافان وستري.","6:23":"وأخذ هارون أليشابع بنت عميناداب أخت نحشون زوجة له, فولدت له ناداب وأبيهو وألعازار وإيثامار.","6:24":"وبنو قورح: أسير وألقانة وأبيأساف. هذه عشائر القورحيين.","6:25":"وألعازار بن هارون أخذ لنفسه من بنات فوطيئيل زوجة, فولدت له فينحاس. هؤلاء هم رؤساء آباء اللاويين بحسب عشائرهم.","6:26":"هذان هما هارون وموسى اللذان قال الرب لهما: «أخرجا بني إسرائيل من أرض مصر» بحسب أجنادهم.","6:27":"هما اللذان كلما فرعون ملك مصر في إخراج بني إسرائيل من مصر. هذان هما موسى وهارون.","6:28":"وكان يوم كلم الرب موسى في أرض مصر","6:29":"أن الرب كلمه قائلا: «أنا الرب. كلم فرعون ملك مصر بكل ما أنا أكلمك به».","6:30":"فقال موسى أمام الرب: «ها أنا أغلف الشفتين. فكيف يسمع لي فرعون؟».","7:1":"فقال الرب لموسى: «انظر! أنا جعلتك إلها لفرعون. وهارون أخوك يكون نبيك.","7:2":"أنت تتكلم بكل ما آمرك, وهارون أخوك يكلم فرعون ليطلق بني إسرائيل من أرضه.","7:3":"ولكني أقسي قلب فرعون وأكثر آياتي وعجائبي في أرض مصر.","7:4":"ولا يسمع لكما فرعون حتى أجعل يدي على مصر, فأخرج أجنادي, شعبي بني إسرائيل من أرض مصر بأحكام عظيمة.","7:5":"فيعرف المصريون أني أنا الرب حينما أمد يدي على مصر وأخرج بني إسرائيل من بينهم».","7:6":"ففعل موسى وهارون كما أمرهما الرب. هكذا فعلا.","7:7":"وكان موسى ابن ثمانين سنة, وهارون ابن ثلاث وثمانين سنة حين كلما فرعون.","7:8":"وكلم الرب موسى وهارون قائلا:","7:9":"«إذا كلمكما فرعون قائلا: هاتيا عجيبة, تقول لهارون: خذ عصاك واطرحها أمام فرعون فتصير ثعبانا».","7:10":"فدخل موسى وهارون إلى فرعون وفعلا هكذا كما أمر الرب. طرح هارون عصاه أمام فرعون وأمام عبيده فصارت ثعبانا.","7:11":"فدعا فرعون أيضا الحكماء والسحرة, ففعل عرافو مصر أيضا بسحرهم كذلك.","7:12":"طرحوا كل واحد عصاه فصارت العصي ثعابين. ولكن عصا هارون ابتلعت عصيهم.","7:13":"فاشتد قلب فرعون فلم يسمع لهما, كما تكلم الرب.","7:14":"ثم قال الرب لموسى: «قلب فرعون غليظ. قد أبى أن يطلق الشعب.","7:15":"اذهب إلى فرعون في الصباح. إنه يخرج إلى الماء, وقف للقائه على حافة النهر. والعصا التي تحولت حية تأخذها في يدك.","7:16":"وتقول له: الرب إله العبرانيين أرسلني إليك قائلا: أطلق شعبي ليعبدوني في البرية. وهوذا حتى الآن لم تسمع.","7:17":"هكذا يقول الرب: بهذا تعرف أني أنا الرب: ها أنا أضرب بالعصا التي في يدي على الماء الذي في النهر فيتحول دما.","7:18":"ويموت السمك الذي في النهر وينتن النهر. فيعاف المصريون أن يشربوا ماء من النهر».","7:19":"ثم قال الرب لموسى: «قل لهارون: خذ عصاك ومد يدك على مياه المصريين, على أنهارهم وعلى سواقيهم, وعلى آجامهم, وعلى كل مجتمعات مياههم لتصير دما. فيكون دم في كل أرض مصر في الأخشاب وفي الأحجار».","7:20":"ففعل هكذا موسى وهارون كما أمر الرب. رفع العصا وضرب الماء الذي في النهر أمام عيني فرعون وأمام عيون عبيده, فتحول كل الماء الذي في النهر دما.","7:21":"ومات السمك الذي في النهر وأنتن النهر, فلم يقدر المصريون أن يشربوا ماء من النهر. وكان الدم في كل أرض مصر.","7:22":"وفعل عرافو مصر كذلك بسحرهم. فاشتد قلب فرعون فلم يسمع لهما, كما تكلم الرب.","7:23":"ثم انصرف فرعون ودخل بيته ولم يوجه قلبه إلى هذا أيضا.","7:24":"وحفر جميع المصريين حوالي النهر لأجل ماء ليشربوا, لأنهم لم يقدروا أن يشربوا من ماء النهر.","7:25":"ولما كملت سبعة أيام بعد ما ضرب الرب النهر","8:1":"قال الرب لموسى: «ادخل إلى فرعون وقل له: هكذا يقول الرب: أطلق شعبي ليعبدوني.","8:2":"وإن كنت تأبى أن تطلقهم فها أنا أضرب جميع تخومك بالضفادع.","8:3":"فيفيض النهر ضفادع. فتصعد وتدخل إلى بيتك وإلى مخدع فراشك وعلى سريرك وإلى بيوت عبيدك وعلى شعبك وإلى تنانيرك وإلى معاجنك.","8:4":"عليك وعلى شعبك وعبيدك تصعد الضفادع».","8:5":"فقال الرب لموسى: «قل لهارون: مد يدك بعصاك على الأنهار والسواقي والآجام, وأصعد الضفادع على أرض مصر».","8:6":"فمد هارون يده على مياه مصر, فصعدت الضفادع وغطت أرض مصر.","8:7":"وفعل كذلك العرافون بسحرهم وأصعدوا الضفادع على أرض مصر.","8:8":"فدعا فرعون موسى وهارون وقال: «صليا إلى الرب ليرفع الضفادع عني وعن شعبي فأطلق الشعب ليذبحوا للرب».","8:9":"فقال موسى لفرعون: «عين لي متى أصلي لأجلك ولأجل عبيدك وشعبك لقطع الضفادع عنك وعن بيوتك. ولكنها تبقى في النهر».","8:10":"فقال: «غدا». فقال: «كقولك. لكي تعرف أن ليس مثل الرب إلهنا.","8:11":"فترتفع الضفادع عنك وعن بيوتك وعبيدك وشعبك, ولكنها تبقى في النهر».","8:12":"ثم خرج موسى وهارون من لدن فرعون, وصرخ موسى إلى الرب من أجل الضفادع التي جعلها على فرعون,","8:13":"ففعل الرب كقول موسى. فماتت الضفادع من البيوت والدور والحقول.","8:14":"وجمعوها كوما كثيرة حتى أنتنت الأرض.","8:15":"فلما رأى فرعون أنه قد حصل الفرج أغلظ قلبه ولم يسمع لهما, كما تكلم الرب.","8:16":"ثم قال الرب لموسى: «قل لهارون: مد عصاك واضرب تراب الأرض ليصير بعوضا في جميع أرض مصر».","8:17":"ففعلا كذلك. مد هارون يده بعصاه وضرب تراب الأرض, فصار البعوض على الناس وعلى البهائم. كل تراب الأرض صار بعوضا في جميع أرض مصر.","8:18":"وفعل كذلك العرافون بسحرهم ليخرجوا البعوض فلم يستطيعوا. وكان البعوض على الناس وعلى البهائم.","8:19":"فقال العرافون لفرعون: «هذا إصبع الله». ولكن اشتد قلب فرعون فلم يسمع لهما, كما تكلم الرب.","8:20":"ثم قال الرب لموسى: «بكر في الصباح وقف أمام فرعون. إنه يخرج إلى الماء. وقل له: هكذا يقول الرب: أطلق شعبي ليعبدوني.","8:21":"فإنه إن كنت لا تطلق شعبي, ها أنا أرسل عليك وعلى عبيدك وعلى شعبك وعلى بيوتك الذبان, فتمتلئ بيوت المصريين ذبانا. وأيضا الأرض التي هم عليها.","8:22":"ولكن أميز في ذلك اليوم أرض جاسان حيث شعبي مقيم حتى لا يكون هناك ذبان. لكي تعلم أني أنا الرب في الأرض.","8:23":"وأجعل فرقا بين شعبي وشعبك. غدا تكون هذه الآية».","8:24":"ففعل الرب هكذا, فدخلت ذبان كثيرة إلى بيت فرعون وبيوت عبيده. وفي كل أرض مصر خربت الأرض من الذبان.","8:25":"فدعا فرعون موسى وهارون وقال: «اذهبوا اذبحوا لإلهكم في هذه الأرض».","8:26":"فقال موسى: «لا يصلح أن نفعل هكذا, لأننا إنما نذبح رجس المصريين للرب إلهنا. إن ذبحنا رجس المصريين أمام عيونهم أفلا يرجموننا؟","8:27":"نذهب سفر ثلاثة أيام في البرية ونذبح للرب إلهنا كما يقول لنا».","8:28":"فقال فرعون: «أنا أطلقكم لتذبحوا للرب إلهكم في البرية, ولكن لا تذهبوا بعيدا. صليا لأجلي».","8:29":"فقال موسى: «ها أنا أخرج من لدنك وأصلي إلى الرب, فترتفع الذبان عن فرعون وعبيده وشعبه غدا. ولكن لا يعد فرعون يخاتل حتى لا يطلق الشعب ليذبح للرب».","8:30":"فخرج موسى من لدن فرعون وصلى إلى الرب.","8:31":"ففعل الرب كقول موسى, فارتفع الذبان عن فرعون وعبيده وشعبه. لم تبق واحدة.","8:32":"ولكن أغلظ فرعون قلبه هذه المرة أيضا فلم يطلق الشعب.","9:1":"ثم قال الرب لموسى: «ادخل إلى فرعون وقل له: هكذا يقول الرب إله العبرانيين: أطلق شعبي ليعبدوني.","9:2":"فإنه إن كنت تأبى أن تطلقهم وكنت تمسكهم بعد,","9:3":"فها يد الرب تكون على مواشيك التي في الحقل, على الخيل والحمير والجمال والبقر والغنم, وبأ ثقيلا جدا.","9:4":"ويميز الرب بين مواشي إسرائيل ومواشي المصريين. فلا يموت من كل ما لبني إسرائيل شيء».","9:5":"وعين الرب وقتا قائلا: «غدا يفعل الرب هذا الأمر في الأرض».","9:6":"ففعل الرب هذا الأمر في الغد. فماتت جميع مواشي المصريين. وأما مواشي بني إسرائيل فلم يمت منها واحد.","9:7":"وأرسل فرعون وإذا مواشي إسرائيل لم يمت منها ولا واحد. ولكن غلظ قلب فرعون فلم يطلق الشعب.","9:8":"ثم قال الرب لموسى وهارون: «خذا ملء أيديكما من رماد الأتون, وليذره موسى نحو السماء أمام عيني فرعون,","9:9":"ليصير غبارا على كل أرض مصر. فيصير على الناس وعلى البهائم دمامل طالعة ببثور في كل أرض مصر».","9:10":"فأخذا رماد الأتون ووقفا أمام فرعون, وذراه موسى نحو السماء, فصار دمامل بثور طالعة في الناس وفي البهائم.","9:11":"ولم يستطع العرافون أن يقفوا أمام موسى من أجل الدمامل, لأن الدمامل كانت في العرافين وفي كل المصريين.","9:12":"ولكن شدد الرب قلب فرعون فلم يسمع لهما, كما كلم الرب موسى.","9:13":"ثم قال الرب لموسى: «بكر في الصباح وقف أمام فرعون وقل له: هكذا يقول الرب إله العبرانيين: أطلق شعبي ليعبدوني.","9:14":"لأني هذه المرة أرسل جميع ضرباتي إلى قلبك وعلى عبيدك وشعبك, لكي تعرف أن ليس مثلي في كل الأرض.","9:15":"فإنه الآن لو كنت أمد يدي وأضربك وشعبك بالوبإ, لكنت تباد من الأرض.","9:16":"ولكن لأجل هذا أقمتك, لكي أريك قوتي, ولكي يخبر باسمي في كل الأرض.","9:17":"أنت معاند بعد لشعبي حتى لا تطلقه.","9:18":"ها أنا غدا مثل الآن أمطر بردا عظيما جدا لم يكن مثله في مصر منذ يوم تأسيسها إلى الآن.","9:19":"فالآن أرسل احم مواشيك وكل ما لك في الحقل. جميع الناس والبهائم الذين يوجدون في الحقل ولا يجمعون إلى البيوت, ينزل عليهم البرد فيموتون».","9:20":"فالذي خاف كلمة الرب من عبيد فرعون هرب بعبيده ومواشيه إلى البيوت.","9:21":"وأما الذي لم يوجه قلبه إلى كلمة الرب فترك عبيده ومواشيه في الحقل.","9:22":"ثم قال الرب لموسى: «مد يدك نحو السماء ليكون برد في كل أرض مصر: على الناس وعلى البهائم وعلى كل عشب الحقل في أرض مصر».","9:23":"فمد موسى عصاه نحو السماء, فأعطى الرب رعودا وبردا, وجرت نار على الأرض, وأمطر الرب بردا على أرض مصر.","9:24":"فكان برد, ونار متواصلة في وسط البرد. شيء عظيم جدا لم يكن مثله في كل أرض مصر منذ صارت أمة.","9:25":"فضرب البرد في كل أرض مصر جميع ما في الحقل من الناس والبهائم. وضرب البرد جميع عشب الحقل وكسر جميع شجر الحقل.","9:26":"إلا أرض جاسان حيث كان بنو إسرائيل, فلم يكن فيها برد.","9:27":"فأرسل فرعون ودعا موسى وهارون وقال لهما: «أخطأت هذه المرة. الرب هو البار وأنا وشعبي الأشرار.","9:28":"صليا إلى الرب, وكفى حدوث رعود الله والبرد, فأطلقكم ولا تعودوا تلبثون».","9:29":"فقال له موسى: «عند خروجي من المدينة أبسط يدي إلى الرب, فتنقطع الرعود ولا يكون البرد أيضا, لكي تعرف أن للرب الأرض.","9:30":"وأما أنت وعبيدك فأنا أعلم أنكم لم تخشوا بعد من الرب الإله».","9:31":"فالكتان والشعير ضربا. لأن الشعير كان مسبلا والكتان مبزرا.","9:32":"وأما الحنطة والقطاني فلم تضرب لأنها كانت متأخرة.","9:33":"فخرج موسى من المدينة من لدن فرعون وبسط يديه إلى الرب, فانقطعت الرعود والبرد ولم ينصب المطر على الأرض.","9:34":"ولكن فرعون لما رأى أن المطر والبرد والرعود انقطعت, عاد يخطئ وأغلظ قلبه هو وعبيده.","9:35":"فاشتد قلب فرعون فلم يطلق بني إسرائيل, كما تكلم الرب عن يد موسى.","10:1":"ثم قال الرب لموسى: «ادخل إلى فرعون, فإني أغلظت قلبه وقلوب عبيده لكي أصنع آياتي هذه بينهم.","10:2":"ولكي تخبر في مسامع ابنك وابن ابنك بما فعلته في مصر, وبآياتي التي صنعتها بينهم, فتعلمون أني أنا الرب».","10:3":"فدخل موسى وهارون إلى فرعون وقالا له: «هكذا يقول الرب إله العبرانيين: إلى متى تأبى أن تخضع لي؟ أطلق شعبي ليعبدوني.","10:4":"فإنه إن كنت تأبى أن تطلق شعبي ها أنا أجيء غدا بجراد على تخومك,","10:5":"فيغطي وجه الأرض حتى لا يستطاع نظر الأرض. ويأكل الفضلة السالمة الباقية لكم من البرد. ويأكل جميع الشجر النابت لكم من الحقل.","10:6":"ويملأ بيوتك وبيوت جميع عبيدك وبيوت جميع المصريين, الأمر الذي لم يره آباؤك ولا آباء آبائك منذ يوم وجدوا على الأرض إلى هذا اليوم». ثم تحول وخرج من لدن فرعون.","10:7":"فقال عبيد فرعون له: «إلى متى يكون هذا لنا فخا؟ أطلق الرجال ليعبدوا الرب إلههم. ألم تعلم بعد أن مصر قد خربت؟».","10:8":"فرد موسى وهارون إلى فرعون, فقال لهما: «اذهبوا اعبدوا الرب إلهكم. ولكن من ومن هم الذين يذهبون؟»","10:9":"فقال موسى: «نذهب بفتياننا وشيوخنا. نذهب ببنينا وبناتنا, بغنمنا وبقرنا, لأن لنا عيدا للرب».","10:10":"فقال لهما: «يكون الرب معكم هكذا كما أطلقكم وأولادكم. انظروا, إن قدام وجوهكم شرا.","10:11":"ليس هكذا. اذهبوا أنتم الرجال واعبدوا الرب. لأنكم لهذا طالبون». فطردا من لدن فرعون.","10:12":"ثم قال الرب لموسى: «مد يدك على أرض مصر لأجل الجراد, ليصعد على أرض مصر ويأكل كل عشب الأرض, كل ما تركه البرد».","10:13":"فمد موسى عصاه على أرض مصر, فجلب الرب على الأرض ريحا شرقية كل ذلك النهار وكل الليل. ولما كان الصباح, حملت الريح الشرقية الجراد,","10:14":"فصعد الجراد على كل أرض مصر, وحل في جميع تخوم مصر. شيء ثقيل جدا لم يكن قبله جراد هكذا مثله, ولا يكون بعده كذلك,","10:15":"وغطى وجه كل الأرض حتى أظلمت الأرض. وأكل جميع عشب الأرض وجميع ثمر الشجر الذي تركه البرد, حتى لم يبق شيء أخضر في الشجر ولا في عشب الحقل في كل أرض مصر».","10:16":"فدعا فرعون موسى وهارون مسرعا وقال: «أخطأت إلى الرب إلهكما وإليكما.","10:17":"والآن اصفحا عن خطيتي هذه المرة فقط, وصليا إلى الرب إلهكما ليرفع عني هذا الموت فقط».","10:18":"فخرج موسى من لدن فرعون وصلى إلى الرب.","10:19":"فرد الرب ريحا غربية شديدة جدا, فحملت الجراد وطرحته إلى بحر سوف. لم تبق جرادة واحدة في كل تخوم مصر.","10:20":"ولكن شدد الرب قلب فرعون فلم يطلق بني إسرائيل.","10:21":"ثم قال الرب لموسى: «مد يدك نحو السماء ليكون ظلام على أرض مصر, حتى يلمس الظلام».","10:22":"فمد موسى يده نحو السماء فكان ظلام دامس في كل أرض مصر ثلاثة أيام.","10:23":"لم يبصر أحد أخاه, ولا قام أحد من مكانه ثلاثة أيام. ولكن جميع بني إسرائيل كان لهم نور في مساكنهم.","10:24":"فدعا فرعون موسى وقال: «اذهبوا اعبدوا الرب. غير أن غنمكم وبقركم تبقى. أولادكم أيضا تذهب معكم».","10:25":"فقال موسى: «أنت تعطي أيضا في أيدينا ذبائح ومحرقات لنصنعها للرب إلهنا,","10:26":"فتذهب مواشينا أيضا معنا. لا يبقى ظلف. لأننا منها نأخذ لعبادة الرب إلهنا. ونحن لا نعرف بماذا نعبد الرب حتى نأتي إلى هناك».","10:27":"ولكن شدد الرب قلب فرعون فلم يشأ أن يطلقهم.","10:28":"وقال له فرعون: «اذهب عني. احترز. لا تر وجهي أيضا. إنك يوم ترى وجهي تموت».","10:29":"فقال موسى: «نعما قلت. أنا لا أعود أرى وجهك أيضا».","11:1":"ثم قال الرب لموسى: «ضربة واحدة أيضا أجلب على فرعون وعلى مصر. بعد ذلك يطلقكم من هنا. وعندما يطلقكم يطردكم طردا من هنا بالتمام.","11:2":"تكلم في مسامع الشعب أن يطلب كل رجل من صاحبه, وكل امرأة من صاحبتها أمتعة فضة وأمتعة ذهب».","11:3":"وأعطى الرب نعمة للشعب في عيون المصريين. وأيضا الرجل موسى كان عظيما جدا في أرض مصر في عيون عبيد فرعون وعيون الشعب.","11:4":"وقال موسى: «هكذا يقول الرب: إني نحو نصف الليل أخرج في وسط مصر,","11:5":"فيموت كل بكر في أرض مصر, من بكر فرعون الجالس على كرسيه إلى بكر الجارية التي خلف الرحى, وكل بكر بهيمة.","11:6":"ويكون صراخ عظيم في كل أرض مصر لم يكن مثله ولا يكون مثله أيضا.","11:7":"ولكن جميع بني إسرائيل لا يسنن كلب لسانه إليهم, لا إلى الناس ولا إلى البهائم. لكي تعلموا أن الرب يميز بين المصريين وإسرائيل.","11:8":"فينزل إلي جميع عبيدك هؤلاء, ويسجدون لي قائلين: اخرج أنت وجميع الشعب الذين في أثرك. وبعد ذلك أخرج». ثم خرج من لدن فرعون في حمو الغضب.","11:9":"وقال الرب لموسى: «لا يسمع لكما فرعون لكي تكثر عجائبي في أرض مصر».","11:10":"وكان موسى وهارون يفعلان كل هذه العجائب أمام فرعون, ولكن شدد الرب قلب فرعون, فلم يطلق بني إسرائيل من أرضه.","12:1":"وكلم الرب موسى وهارون في أرض مصر قائلا:","12:2":"«هذا الشهر يكون لكم رأس الشهور. هو لكم أول شهور السنة.","12:3":"كلما كل جماعة إسرائيل قائلين: في العاشر من هذا الشهر يأخذون لهم كل واحد شاة بحسب بيوت الآباء, شاة للبيت.","12:4":"وإن كان البيت صغيرا عن أن يكون كفوا لشاة, يأخذ هو وجاره القريب من بيته بحسب عدد النفوس. كل واحد على حسب أكله تحسبون للشاة.","12:5":"تكون لكم شاة صحيحة ذكرا ابن سنة, تأخذونه من الخرفان أو من المواعز.","12:6":"ويكون عندكم تحت الحفظ إلى اليوم الرابع عشر من هذا الشهر. ثم يذبحه كل جمهور جماعة إسرائيل في العشية.","12:7":"ويأخذون من الدم ويجعلونه على القائمتين والعتبة العليا في البيوت التي يأكلونه فيها.","12:8":"ويأكلون اللحم تلك الليلة مشويا بالنار مع فطير. على أعشاب مرة يأكلونه.","12:9":"لا تأكلوا منه نيئا أو طبيخا مطبوخا بالماء, بل مشويا بالنار. رأسه مع أكارعه وجوفه.","12:10":"ولا تبقوا منه إلى الصباح. والباقي منه إلى الصباح, تحرقونه بالنار.","12:11":"وهكذا تأكلونه: أحقاؤكم مشدودة, وأحذيتكم في أرجلكم, وعصيكم في أيديكم. وتأكلونه بعجلة. هو فصح للرب.","12:12":"فإني أجتاز في أرض مصر هذه الليلة, وأضرب كل بكر في أرض مصر من الناس والبهائم. وأصنع أحكاما بكل آلهة المصريين. أنا الرب.","12:13":"ويكون لكم الدم علامة على البيوت التي أنتم فيها, فأرى الدم وأعبر عنكم, فلا يكون عليكم ضربة للهلاك حين أضرب أرض مصر.","12:14":"ويكون لكم هذا اليوم تذكارا فتعيدونه عيدا للرب. في أجيالكم تعيدونه فريضة أبدية.","12:15":"«سبعة أيام تأكلون فطيرا. اليوم الأول تعزلون الخمير من بيوتكم, فإن كل من أكل خميرا من اليوم الأول إلى اليوم السابع تقطع تلك النفس من إسرائيل.","12:16":"ويكون لكم في اليوم الأول محفل مقدس, وفي اليوم السابع محفل مقدس. لا يعمل فيهما عمل ما إلا ما تأكله كل نفس, فذلك وحده يعمل منكم.","12:17":"وتحفظون الفطير لأني في هذا اليوم عينه أخرجت أجنادكم من أرض مصر, فتحفظون هذا اليوم في أجيالكم فريضة أبدية.","12:18":"في الشهر الأول, في اليوم الرابع عشر من الشهر, مساء, تأكلون فطيرا إلى اليوم الحادي والعشرين من الشهر مساء.","12:19":"سبعة أيام لا يوجد خمير في بيوتكم. فإن كل من أكل مختمرا تقطع تلك النفس من جماعة إسرائيل, الغريب مع مولود الأرض.","12:20":"لا تأكلوا شيئا مختمرا. في جميع مساكنكم تأكلون فطيرا».","12:21":"فدعا موسى جميع شيوخ إسرائيل وقال لهم: «اسحبوا وخذوا لكم غنما بحسب عشائركم واذبحوا الفصح.","12:22":"وخذوا باقة زوفا واغمسوها في الدم الذي في الطست ومسوا العتبة العليا والقائمتين بالدم الذي في الطست. وأنتم لا يخرج أحد منكم من باب بيته حتى الصباح,","12:23":"فإن الرب يجتاز ليضرب المصريين. فحين يرى الدم على العتبة العليا والقائمتين يعبر الرب عن الباب ولا يدع المهلك يدخل بيوتكم ليضرب.","12:24":"فتحفظون هذا الأمر فريضة لك ولأولادك إلى الأبد.","12:25":"ويكون حين تدخلون الأرض التي يعطيكم الرب كما تكلم, أنكم تحفظون هذه الخدمة.","12:26":"ويكون حين يقول لكم أولادكم: ما هذه الخدمة لكم؟","12:27":"أنكم تقولون: هي ذبيحة فصح للرب الذي عبر عن بيوت بني إسرائيل في مصر لما ضرب المصريين وخلص بيوتنا». فخر الشعب وسجدوا.","12:28":"ومضى بنو إسرائيل وفعلوا كما أمر الرب موسى وهارون. هكذا فعلوا.","12:29":"فحدث في نصف الليل أن الرب ضرب كل بكر في أرض مصر, من بكر فرعون الجالس على كرسيه إلى بكر الأسير الذي في السجن, وكل بكر بهيمة.","12:30":"فقام فرعون ليلا هو وكل عبيده وجميع المصريين. وكان صراخ عظيم في مصر, لأنه لم يكن بيت ليس فيه ميت.","12:31":"فدعا موسى وهارون ليلا وقال: «قوموا اخرجوا من بين شعبي أنتما وبنو إسرائيل جميعا, واذهبوا اعبدوا الرب كما تكلمتم.","12:32":"خذوا غنمكم أيضا وبقركم كما تكلمتم واذهبوا. وباركوني أيضا».","12:33":"وألح المصريون على الشعب ليطلقوهم عاجلا من الأرض, لأنهم قالوا: «جميعنا أموات».","12:34":"فحمل الشعب عجينهم قبل أن يختمر, ومعاجنهم مصرورة في ثيابهم على أكتافهم.","12:35":"وفعل بنو إسرائيل بحسب قول موسى. طلبوا من المصريين أمتعة فضة وأمتعة ذهب وثيابا.","12:36":"وأعطى الرب نعمة للشعب في عيون المصريين حتى أعاروهم. فسلبوا المصريين.","12:37":"فارتحل بنو إسرائيل من رعمسيس إلى سكوت, نحو ست مئة ألف ماش من الرجال عدا الأولاد.","12:38":"وصعد معهم لفيف كثير أيضا مع غنم وبقر, مواش وافرة جدا.","12:39":"وخبزوا العجين الذي أخرجوه من مصر خبز ملة فطيرا, إذ كان لم يختمر. لأنهم طردوا من مصر ولم يقدروا أن يتأخروا, فلم يصنعوا لأنفسهم زادا.","12:40":"وأما إقامة بني إسرائيل التي أقاموها في مصر فكانت أربع مئة وثلاثين سنة.","12:41":"وكان عند نهاية أربع مئة وثلاثين سنة, في ذلك اليوم عينه, أن جميع أجناد الرب خرجت من أرض مصر.","12:42":"هي ليلة تحفظ للرب لإخراجه إياهم من أرض مصر. هذه الليلة هي للرب. تحفظ من جميع بني إسرائيل في أجيالهم.","12:43":"وقال الرب لموسى وهارون: «هذه فريضة الفصح: كل ابن غريب لا يأكل منه.","12:44":"ولكن كل عبد رجل مبتاع بفضة تختنه ثم يأكل منه.","12:45":"النزيل والأجير لا يأكلان منه.","12:46":"في بيت واحد يؤكل. لا تخرج من اللحم من البيت إلى خارج, وعظما لا تكسروا منه.","12:47":"كل جماعة إسرائيل يصنعونه.","12:48":"وإذا نزل عندك نزيل وصنع فصحا للرب, فليختن منه كل ذكر, ثم يتقدم ليصنعه, فيكون كمولود الأرض. وأما كل أغلف فلا يأكل منه.","12:49":"تكون شريعة واحدة لمولود الأرض وللنزيل النازل بينكم».","12:50":"ففعل جميع بني إسرائيل كما أمر الرب موسى وهارون. هكذا فعلوا.","12:51":"وكان في ذلك اليوم عينه أن الرب أخرج بني إسرائيل من أرض مصر بحسب أجنادهم.","13:1":"وكلم الرب موسى قائلا:","13:2":"«قدس لي كل بكر, كل فاتح رحم من بني إسرائيل, من الناس ومن البهائم. إنه لي».","13:3":"وقال موسى للشعب: «اذكروا هذا اليوم الذي فيه خرجتم من مصر من بيت العبودية, فإنه بيد قوية أخرجكم الرب من هنا. ولا يؤكل خمير.","13:4":"اليوم أنتم خارجون في شهر أبيب.","13:5":"ويكون متى أدخلك الرب أرض الكنعانيين والحثيين والأموريين والحويين واليبوسيين التي حلف لآبائك أن يعطيك, أرضا تفيض لبنا وعسلا, أنك تصنع هذه الخدمة في هذا الشهر.","13:6":"سبعة أيام تأكل فطيرا, وفي اليوم السابع عيد للرب.","13:7":"فطير يؤكل السبعة الأيام, ولا يرى عندك مختمر, ولا يرى عندك خمير في جميع تخومك.","13:8":"«وتخبر ابنك في ذلك اليوم قائلا: من أجل ما صنع إلي الرب حين أخرجني من مصر.","13:9":"ويكون لك علامة على يدك, وتذكارا بين عينيك, لكي تكون شريعة الرب في فمك. لأنه بيد قوية أخرجك الرب من مصر.","13:10":"فتحفظ هذه الفريضة في وقتها من سنة إلى سنة.","13:11":"«ويكون متى أدخلك الرب أرض الكنعانيين كما حلف لك ولآبائك, وأعطاك إياها,","13:12":"أنك تقدم للرب كل فاتح رحم, وكل بكر من نتاج البهائم التي تكون لك. الذكور للرب.","13:13":"ولكن كل بكر حمار تفديه بشاة. وإن لم تفده فتكسر عنقه. وكل بكر إنسان من أولادك تفديه.","13:14":"«ويكون متى سألك ابنك غدا قائلا: ما هذا؟ تقول له: بيد قوية أخرجنا الرب من مصر من بيت العبودية.","13:15":"وكان لما تقسى فرعون عن إطلاقنا أن الرب قتل كل بكر في أرض مصر, من بكر الناس إلى بكر البهائم. لذلك أنا أذبح للرب الذكور من كل فاتح رحم, وأفدي كل بكر من أولادي.","13:16":"فيكون علامة على يدك, وعصابة بين عينيك. لأنه بيد قوية أخرجنا الرب من مصر».","13:17":"وكان لما أطلق فرعون الشعب أن الله لم يهدهم في طريق أرض الفلسطينيين مع أنها قريبة, لأن الله قال: «لئلا يندم الشعب إذا رأوا حربا ويرجعوا إلى مصر».","13:18":"فأدار الله الشعب في طريق برية بحر سوف. وصعد بنو إسرائيل متجهزين من أرض مصر.","13:19":"وأخذ موسى عظام يوسف معه, لأنه كان قد استحلف بني إسرائيل بحلف قائلا: «إن الله سيفتقدكم فتصعدون عظامي من هنا معكم».","13:20":"وارتحلوا من سكوت ونزلوا في إيثام في طرف البرية.","13:21":"وكان الرب يسير أمامهم نهارا في عمود سحاب ليهديهم في الطريق, وليلا في عمود نار ليضيء لهم. لكي يمشوا نهارا وليلا.","13:22":"لم يبرح عمود السحاب نهارا وعمود النار ليلا من أمام الشعب.","14:1":"وكلم الرب موسى قائلا:","14:2":"«كلم بني إسرائيل أن يرجعوا وينزلوا أمام فم الحيروث بين مجدل والبحر, أمام بعل صفون. مقابله تنزلون عند البحر.","14:3":"فيقول فرعون عن بني إسرائيل: هم مرتبكون في الأرض. قد استغلق عليهم القفر.","14:4":"وأشدد قلب فرعون حتى يسعى وراءهم, فأتمجد بفرعون وبجميع جيشه, ويعرف المصريون أني أنا الرب». ففعلوا هكذا.","14:5":"فلما أخبر ملك مصر أن الشعب قد هرب, تغير قلب فرعون وعبيده على الشعب. فقالوا: «ماذا فعلنا حتى أطلقنا إسرائيل من خدمتنا؟»","14:6":"فشد مركبته وأخذ قومه معه.","14:7":"وأخذ ست مئة مركبة منتخبة وسائر مركبات مصر وجنودا مركبية على جميعها.","14:8":"وشدد الرب قلب فرعون ملك مصر حتى سعى وراء بني إسرائيل, وبنو إسرائيل خارجون بيد رفيعة.","14:9":"فسعى المصريون وراءهم وأدركوهم. جميع خيل مركبات فرعون وفرسانه وجيشه, وهم نازلون عند البحر عند فم الحيروث, أمام بعل صفون.","14:10":"فلما اقترب فرعون رفع بنو إسرائيل عيونهم, وإذا المصريون راحلون وراءهم. ففزعوا جدا, وصرخ بنو إسرائيل إلى الرب.","14:11":"وقالوا لموسى: «هل لأنه ليست قبور في مصر أخذتنا لنموت في البرية؟ ماذا صنعت بنا حتى أخرجتنا من مصر؟","14:12":"أليس هذا هو الكلام الذي كلمناك به في مصر قائلين: كف عنا فنخدم المصريين؟ لأنه خير لنا أن نخدم المصريين من أن نموت في البرية».","14:13":"فقال موسى للشعب: «لا تخافوا. قفوا وانظروا خلاص الرب الذي يصنعه لكم اليوم. فإنه كما رأيتم المصريين اليوم, لا تعودون ترونهم أيضا إلى الأبد.","14:14":"الرب يقاتل عنكم وأنتم تصمتون».","14:15":"فقال الرب لموسى: «ما لك تصرخ إلي؟ قل لبني إسرائيل أن يرحلوا.","14:16":"وارفع أنت عصاك ومد يدك على البحر وشقه, فيدخل بنو إسرائيل في وسط البحر على اليابسة.","14:17":"وها أنا أشدد قلوب المصريين حتى يدخلوا وراءهم, فأتمجد بفرعون وكل جيشه, بمركباته وفرسانه.","14:18":"فيعرف المصريون أني أنا الرب حين أتمجد بفرعون ومركباته وفرسانه».","14:19":"فانتقل ملاك الله السائر أمام عسكر إسرائيل وسار وراءهم, وانتقل عمود السحاب من أمامهم ووقف وراءهم.","14:20":"فدخل بين عسكر المصريين وعسكر إسرائيل, وصار السحاب والظلام وأضاء الليل. فلم يقترب هذا إلى ذاك كل الليل.","14:21":"ومد موسى يده على البحر, فأجرى الرب البحر بريح شرقية شديدة كل الليل, وجعل البحر يابسة وانشق الماء.","14:22":"فدخل بنو إسرائيل في وسط البحر على اليابسة, والماء سور لهم عن يمينهم وعن يسارهم.","14:23":"وتبعهم المصريون ودخلوا وراءهم. جميع خيل فرعون ومركباته وفرسانه إلى وسط البحر.","14:24":"وكان في هزيع الصبح أن الرب أشرف على عسكر المصريين في عمود النار والسحاب, وأزعج عسكر المصريين,","14:25":"وخلع بكر مركباتهم حتى ساقوها بثقلة. فقال المصريون: «نهرب من إسرائيل, لأن الرب يقاتل المصريين عنهم».","14:26":"فقال الرب لموسى: «مد يدك على البحر ليرجع الماء على المصريين, على مركباتهم وفرسانهم».","14:27":"فمد موسى يده على البحر فرجع البحر عند إقبال الصبح إلى حاله الدائمة, والمصريون هاربون إلى لقائه. فدفع الرب المصريين في وسط البحر.","14:28":"فرجع الماء وغطى مركبات وفرسان جميع جيش فرعون الذي دخل وراءهم في البحر. لم يبق منهم ولا واحد.","14:29":"وأما بنو إسرائيل فمشوا على اليابسة في وسط البحر, والماء سور لهم عن يمينهم وعن يسارهم.","14:30":"فخلص الرب في ذلك اليوم إسرائيل من يد المصريين. ونظر إسرائيل المصريين أمواتا على شاطئ البحر.","14:31":"ورأى إسرائيل الفعل العظيم الذي صنعه الرب بالمصريين, فخاف الشعب الرب وآمنوا بالرب وبعبده موسى.","15:1":"حينئذ رنم موسى وبنو إسرائيل هذه التسبيحة للرب وقالوا: «أرنم للرب فإنه قد تعظم. الفرس وراكبه طرحهما في البحر.","15:2":"الرب قوتي ونشيدي, وقد صار خلاصي. هذا إلهي فأمجده, إله أبي فأرفعه.","15:3":"الرب رجل الحرب. الرب اسمه.","15:4":"مركبات فرعون وجيشه ألقاهما في البحر, فغرق أفضل جنوده المركبية في بحر سوف,","15:5":"تغطيهم اللجج. قد هبطوا في الأعماق كحجر.","15:6":"يمينك يا رب معتزة بالقدرة. يمينك يا رب تحطم العدو.","15:7":"وبكثرة عظمتك تهدم مقاوميك. ترسل سخطك فيأكلهم كالقش,","15:8":"وبريح أنفك تراكمت المياه. انتصبت المجاري كرابية. تجمدت اللجج في قلب البحر.","15:9":"قال العدو: أتبع, أدرك, أقسم غنيمة. تمتلئ منهم نفسي. أجرد سيفي. تفنيهم يدي.","15:10":"نفخت بريحك فغطاهم البحر. غاصوا كالرصاص في مياه غامرة.","15:11":"من مثلك بين الآلهة يا رب؟ من مثلك معتزا في القداسة, مخوفا بالتسابيح, صانعا عجائب؟","15:12":"تمد يمينك فتبتلعهم الأرض.","15:13":"ترشد برأفتك الشعب الذي فديته. تهديه بقوتك إلى مسكن قدسك.","15:14":"يسمع الشعوب فيرتعدون. تأخذ الرعدة سكان فلسطين.","15:15":"حينئذ يندهش أمراء أدوم. أقوياء موآب تأخذهم الرجفة. يذوب جميع سكان كنعان.","15:16":"تقع عليهم الهيبة والرعب. بعظمة ذراعك يصمتون كالحجر حتى يعبر شعبك يا رب. حتى يعبر الشعب الذي اقتنيته.","15:17":"تجيء بهم وتغرسهم في جبل ميراثك, المكان الذي صنعته يا رب لسكنك المقدس الذي هيأته يداك يا رب.","15:18":"الرب يملك إلى الدهر والأبد».","15:19":"فإن خيل فرعون دخلت بمركباته وفرسانه إلى البحر, ورد الرب عليهم ماء البحر. وأما بنو إسرائيل فمشوا على اليابسة في وسط البحر.","15:20":"فأخذت مريم النبية أخت هارون الدف بيدها, وخرجت جميع النساء وراءها بدفوف ورقص.","15:21":"وأجابتهم مريم: «رنموا للرب فإنه قد تعظم. الفرس وراكبه طرحهما في البحر».","15:22":"ثم ارتحل موسى بإسرائيل من بحر سوف وخرجوا إلى برية شور. فساروا ثلاثة أيام في البرية ولم يجدوا ماء.","15:23":"فجاءوا إلى مارة, ولم يقدروا أن يشربوا ماء من مارة لأنه مر. لذلك دعي اسمها «مارة».","15:24":"فتذمر الشعب على موسى قائلين: «ماذا نشرب؟»","15:25":"فصرخ إلى الرب. فأراه الرب شجرة فطرحها في الماء فصار الماء عذبا. هناك وضع له فريضة وحكما, وهناك امتحنه.","15:26":"فقال: «إن كنت تسمع لصوت الرب إلهك, وتصنع الحق في عينيه, وتصغى إلى وصاياه وتحفظ جميع فرائضه, فمرضا ما مما وضعته على المصريين لا أضع عليك. فإني أنا الرب شافيك».","15:27":"ثم جاءوا إلى إيليم وهناك اثنتا عشرة عين ماء وسبعون نخلة. فنزلوا هناك عند الماء.","16:1":"ثم ارتحلوا من إيليم. وأتى كل جماعة بني إسرائيل إلى برية سين, التي بين إيليم وسيناء في اليوم الخامس عشر من الشهر الثاني بعد خروجهم من أرض مصر.","16:2":"فتذمر كل جماعة بني إسرائيل على موسى وهارون في البرية.","16:3":"وقال لهما بنو إسرائيل: «ليتنا متنا بيد الرب في أرض مصر, إذ كنا جالسين عند قدور اللحم نأكل خبزا للشبع. فإنكما أخرجتمانا إلى هذا القفر لكي تميتا كل هذا الجمهور بالجوع».","16:4":"فقال الرب لموسى: «ها أنا أمطر لكم خبزا من السماء. فيخرج الشعب ويلتقطون حاجة اليوم بيومها. لكي أمتحنهم, أيسلكون في ناموسي أم لا.","16:5":"ويكون في اليوم السادس أنهم يهيئون ما يجيئون به فيكون ضعف ما يلتقطونه يوما فيوما».","16:6":"فقال موسى وهارون لجميع بني إسرائيل: «في المساء تعلمون أن الرب أخرجكم من أرض مصر.","16:7":"وفي الصباح ترون مجد الرب لاستماعه تذمركم على الرب. وأما نحن فماذا حتى تتذمروا علينا؟».","16:8":"وقال موسى: «ذلك بأن الرب يعطيكم في المساء لحما لتأكلوا, وفي الصباح خبزا لتشبعوا, لاستماع الرب تذمركم الذي تتذمرون عليه. وأما نحن فماذا؟ ليس علينا تذمركم بل على الرب».","16:9":"وقال موسى لهارون: «قل لكل جماعة بني إسرائيل: اقتربوا إلى أمام الرب لأنه قد سمع تذمركم».","16:10":"فحدث إذ كان هارون يكلم كل جماعة بني إسرائيل أنهم التفتوا نحو البرية, وإذا مجد الرب قد ظهر في السحاب.","16:11":"فكلم الرب موسى قائلا:","16:12":"«سمعت تذمر بني إسرائيل. كلمهم قائلا: في العشية تأكلون لحما, وفي الصباح تشبعون خبزا, وتعلمون أني أنا الرب إلهكم».","16:13":"فكان في المساء أن السلوى صعدت وغطت المحلة. وفي الصباح كان سقيط الندى حوالي المحلة.","16:14":"ولما ارتفع سقيط الندى إذا على وجه البرية شيء دقيق مثل قشور. دقيق كالجليد على الأرض.","16:15":"فلما رأى بنو إسرائيل قالوا بعضهم لبعض: «من هو؟» لأنهم لم يعرفوا ما هو. فقال لهم موسى: «هو الخبز الذي أعطاكم الرب لتأكلوا.","16:16":"هذا هو الشيء الذي أمر به الرب. التقطوا منه كل واحد على حسب أكله. عمرا للرأس على عدد نفوسكم تأخذون, كل واحد للذين في خيمته».","16:17":"ففعل بنو إسرائيل هكذا, والتقطوا بين مكثر ومقلل.","16:18":"ولما كالوا بالعمر, لم يفضل المكثر والمقلل لم ينقص. كانوا قد التقطوا كل واحد على حسب أكله.","16:19":"وقال لهم موسى: «لا يبق أحد منه إلى الصباح».","16:20":"لكنهم لم يسمعوا لموسى, بل أبقى منه أناس إلى الصباح, فتولد فيه دود وأنتن. فسخط عليهم موسى.","16:21":"وكانوا يلتقطونه صباحا فصباحا كل واحد على حسب أكله. وإذا حميت الشمس كان يذوب.","16:22":"ثم كان في اليوم السادس أنهم التقطوا خبزا مضاعفا, عمرين للواحد. فجاء كل رؤساء الجماعة وأخبروا موسى.","16:23":"فقال لهم: «هذا ما قال الرب: غدا عطلة, سبت مقدس للرب. اخبزوا ما تخبزون واطبخوا ما تطبخون. وكل ما فضل ضعوه عندكم ليحفظ إلى الغد».","16:24":"فوضعوه إلى الغد كما أمر موسى, فلم ينتن ولا صار فيه دود.","16:25":"فقال موسى: «كلوه اليوم, لأن للرب اليوم سبتا. اليوم لا تجدونه في الحقل.","16:26":"ستة أيام تلتقطونه, وأما اليوم السابع ففيه سبت, لا يوجد فيه».","16:27":"وحدث في اليوم السابع أن بعض الشعب خرجوا ليلتقطوا فلم يجدوا.","16:28":"فقال الرب لموسى: «إلى متى تأبون أن تحفظوا وصاياي وشرائعي؟","16:29":"انظروا! إن الرب أعطاكم السبت. لذلك هو يعطيكم في اليوم السادس خبز يومين. اجلسوا كل واحد في مكانه. لا يخرج أحد من مكانه في اليوم السابع».","16:30":"فاستراح الشعب في اليوم السابع.","16:31":"ودعا بيت إسرائيل اسمه «منا». وهو كبزر الكزبرة, أبيض, وطعمه كرقاق بعسل.","16:32":"وقال موسى: «هذا هو الشيء الذي أمر به الرب. ملء العمر منه يكون للحفظ في أجيالكم. لكي يروا الخبز الذي أطعمتكم في البرية حين أخرجتكم من أرض مصر».","16:33":"وقال موسى لهارون: «خذ قسطا واحدا واجعل فيه ملء العمر منا, وضعه أمام الرب للحفظ في أجيالكم».","16:34":"كما أمر الرب موسى وضعه هارون أمام الشهادة للحفظ.","16:35":"وأكل بنو إسرائيل المن أربعين سنة حتى جاءوا إلى أرض عامرة. أكلوا المن حتى جاءوا إلى طرف أرض كنعان.","16:36":"وأما العمر فهو عشر الإيفة.","17:1":"ثم ارتحل كل جماعة بني إسرائيل من برية سين بحسب مراحلهم على موجب أمر الرب, ونزلوا في رفيديم. ولم يكن ماء ليشرب الشعب.","17:2":"فخاصم الشعب موسى وقالوا: «أعطونا ماء لنشرب.» فقال لهم موسى: «لماذا تخاصمونني؟ لماذا تجربون الرب؟»","17:3":"وعطش هناك الشعب إلى الماء, وتذمر الشعب على موسى وقالوا: «لماذا أصعدتنا من مصر لتميتنا وأولادنا ومواشينا بالعطش؟»","17:4":"فصرخ موسى إلى الرب قائلا: «ماذا أفعل بهذا الشعب؟ بعد قليل يرجمونني».","17:5":"فقال الرب لموسى: «مر قدام الشعب, وخذ معك من شيوخ إسرائيل. وعصاك التي ضربت بها النهر خذها في يدك واذهب.","17:6":"ها أنا أقف أمامك هناك على الصخرة في حوريب, فتضرب الصخرة فيخرج منها ماء ليشرب الشعب». ففعل موسى هكذا أمام عيون شيوخ إسرائيل.","17:7":"ودعا اسم الموضع «مسة ومريبة» من أجل مخاصمة بني إسرائيل, ومن أجل تجربتهم للرب قائلين: «أفي وسطنا الرب أم لا؟».","17:8":"وأتى عماليق وحارب إسرائيل في رفيديم.","17:9":"فقال موسى ليشوع: «انتخب لنا رجالا واخرج حارب عماليق. وغدا أقف أنا على رأس التلة وعصا الله في يدي».","17:10":"ففعل يشوع كما قال له موسى ليحارب عماليق. وأما موسى وهارون وحور فصعدوا على رأس التلة.","17:11":"وكان إذا رفع موسى يده أن إسرائيل يغلب, وإذا خفض يده أن عماليق يغلب.","17:12":"فلما صارت يدا موسى ثقيلتين, أخذا حجرا ووضعاه تحته فجلس عليه. ودعم هارون وحور يديه, الواحد من هنا والآخر من هناك. فكانت يداه ثابتتين إلى غروب الشمس.","17:13":"فهزم يشوع عماليق وقومه بحد السيف.","17:14":"فقال الرب لموسى: «اكتب هذا تذكارا في الكتاب, وضعه في مسامع يشوع. فإني سوف أمحو ذكر عماليق من تحت السماء».","17:15":"فبنى موسى مذبحا ودعا اسمه «يهوه نسي».","17:16":"وقال: «إن اليد على كرسي الرب. للرب حرب مع عماليق من دور إلى دور».","18:1":"فسمع يثرون كاهن مديان, حمو موسى, كل ما صنع الله إلى موسى وإلى إسرائيل شعبه: أن الرب أخرج إسرائيل من مصر.","18:2":"فأخذ يثرون حمو موسى صفورة امرأة موسى بعد صرفها","18:3":"وابنيها, اللذين اسم أحدهما جرشوم, لأنه قال: «كنت نزيلا في أرض غريبة».","18:4":"واسم الآخر أليعازر, لأنه قال: «إله أبي كان عوني وأنقذني من سيف فرعون».","18:5":"وأتى يثرون حمو موسى وابناه وامرأته إلى موسى إلى البرية حيث كان نازلا عند جبل الله.","18:6":"فقال لموسى: «أنا حموك يثرون, آت إليك وامرأتك وابناها معها».","18:7":"فخرج موسى لاستقبال حميه وسجد وقبله. وسأل كل واحد صاحبه عن سلامته, ثم دخلا إلى الخيمة.","18:8":"فقص موسى على حميه كل ما صنع الرب بفرعون والمصريين من أجل إسرائيل, وكل المشقة التي أصابتهم في الطريق فخلصهم الرب.","18:9":"ففرح يثرون بجميع الخير الذي صنعه إلى إسرائيل الرب, الذي أنقذه من أيدي المصريين.","18:10":"وقال يثرون: «مبارك الرب الذي أنقذكم من أيدي المصريين ومن يد فرعون. الذي أنقذ الشعب من تحت أيدي المصريين.","18:11":"الآن علمت أن الرب أعظم من جميع الآلهة, لأنه في الشيء الذي بغوا به كان عليهم».","18:12":"فأخذ يثرون حمو موسى محرقة وذبائح لله. وجاء هارون وجميع شيوخ إسرائيل ليأكلوا طعاما مع حمي موسى أمام الله.","18:13":"وحدث في الغد أن موسى جلس ليقضي للشعب. فوقف الشعب عند موسى من الصباح إلى المساء.","18:14":"فلما رأى حمو موسى كل ما هو صانع للشعب, قال: «ما هذا الأمر الذي أنت صانع للشعب؟ ما بالك جالسا وحدك وجميع الشعب واقف عندك من الصباح إلى المساء؟»","18:15":"فقال موسى لحميه: «إن الشعب يأتي إلي ليسأل الله.","18:16":"إذا كان لهم دعوى يأتون إلي فأقضي بين الرجل وصاحبه, وأعرفهم فرائض الله وشرائعه».","18:17":"فقال حمو موسى له: «ليس جيدا الأمر الذي أنت صانع.","18:18":"إنك تكل أنت وهذا الشعب الذي معك جميعا, لأن الأمر أعظم منك. لا تستطيع أن تصنعه وحدك.","18:19":"الآن اسمع لصوتي فأنصحك. فليكن الله معك. كن أنت للشعب أمام الله, وقدم أنت الدعاوي إلى الله,","18:20":"وعلمهم الفرائض والشرائع, وعرفهم الطريق الذي يسلكونه, والعمل الذي يعملونه.","18:21":"وأنت تنظر من جميع الشعب ذوي قدرة خائفين الله, أمناء مبغضين الرشوة, وتقيمهم عليهم رؤساء ألوف, ورؤساء مئات, ورؤساء خماسين, ورؤساء عشرات,","18:22":"فيقضون للشعب كل حين. ويكون أن كل الدعاوي الكبيرة يجيئون بها إليك, وكل الدعاوي الصغيرة يقضون هم فيها. وخفف عن نفسك, فهم يحملون معك.","18:23":"إن فعلت هذا الأمر وأوصاك الله تستطيع القيام. وكل هذا الشعب أيضا يأتي إلى مكانه بالسلام».","18:24":"فسمع موسى لصوت حميه وفعل كل ما قال.","18:25":"واختار موسى ذوي قدرة من جميع إسرائيل وجعلهم رؤوسا على الشعب, رؤساء ألوف, ورؤساء مئات, ورؤساء خماسين, ورؤساء عشرات.","18:26":"فكانوا يقضون للشعب كل حين. الدعاوي العسرة يجيئون بها إلى موسى, وكل الدعاوي الصغيرة يقضون هم فيها.","18:27":"ثم صرف موسى حماه فمضى إلى أرضه.","19:1":"في الشهر الثالث بعد خروج بني إسرائيل من أرض مصر, في ذلك اليوم جاءوا إلى برية سيناء.","19:2":"ارتحلوا من رفيديم وجاءوا إلى برية سيناء فنزلوا في البرية. هناك نزل إسرائيل مقابل الجبل.","19:3":"وأما موسى فصعد إلى الله. فناداه الرب من الجبل قائلا: «هكذا تقول لبيت يعقوب, وتخبر بني إسرائيل:","19:4":"أنتم رأيتم ما صنعت بالمصريين. وأنا حملتكم على أجنحة النسور وجئت بكم إلي.","19:5":"فالآن إن سمعتم لصوتي, وحفظتم عهدي تكونون لي خاصة من بين جميع الشعوب. فإن لي كل الأرض.","19:6":"وأنتم تكونون لي مملكة كهنة وأمة مقدسة. هذه هي الكلمات التي تكلم بها بني إسرائيل».","19:7":"فجاء موسى ودعا شيوخ الشعب ووضع قدامهم كل هذه الكلمات التي أوصاه بها الرب.","19:8":"فأجاب جميع الشعب معا وقالوا: «كل ما تكلم به الرب نفعل». فرد موسى كلام الشعب إلى الرب.","19:9":"فقال الرب لموسى: «ها أنا آت إليك في ظلام السحاب لكي يسمع الشعب حينما أتكلم معك, فيؤمنوا بك أيضا إلى الأبد». وأخبر موسى الرب بكلام الشعب.","19:10":"فقال الرب لموسى: «اذهب إلى الشعب وقدسهم اليوم وغدا, وليغسلوا ثيابهم,","19:11":"ويكونوا مستعدين لليوم الثالث. لأنه في اليوم الثالث ينزل الرب أمام عيون جميع الشعب على جبل سيناء.","19:12":"وتقيم للشعب حدودا من كل ناحية, قائلا: احترزوا من أن تصعدوا إلى الجبل أو تمسوا طرفه. كل من يمس الجبل يقتل قتلا.","19:13":"لا تمسه يد بل يرجم رجما أو يرمى رميا. بهيمة كان أم إنسانا لا يعيش. أما عند صوت البوق فهم يصعدون إلى الجبل».","19:14":"فانحدر موسى من الجبل إلى الشعب, وقدس الشعب وغسلوا ثيابهم.","19:15":"وقال للشعب: «كونوا مستعدين لليوم الثالث. لا تقربوا امرأة».","19:16":"وحدث في اليوم الثالث لما كان الصباح أنه صارت رعود وبروق وسحاب ثقيل على الجبل, وصوت بوق شديد جدا. فارتعد كل الشعب الذي في المحلة.","19:17":"وأخرج موسى الشعب من المحلة لملاقاة الله, فوقفوا في أسفل الجبل.","19:18":"وكان جبل سيناء كله يدخن من أجل أن الرب نزل عليه بالنار, وصعد دخانه كدخان الأتون, وارتجف كل الجبل جدا.","19:19":"فكان صوت البوق يزداد اشتدادا جدا, وموسى يتكلم والله يجيبه بصوت.","19:20":"ونزل الرب على جبل سيناء, إلى رأس الجبل, ودعا الله موسى إلى رأس الجبل. فصعد موسى.","19:21":"فقال الرب لموسى: «انحدر حذر الشعب لئلا يقتحموا إلى الرب لينظروا, فيسقط منهم كثيرون.","19:22":"وليتقدس أيضا الكهنة الذين يقتربون إلى الرب لئلا يبطش بهم الرب».","19:23":"فقال موسى للرب: «لا يقدر الشعب أن يصعد إلى جبل سيناء, لأنك أنت حذرتنا قائلا: أقم حدودا للجبل وقدسه».","19:24":"فقال له الرب: «اذهب انحدر ثم اصعد أنت وهارون معك. وأما الكهنة والشعب فلا يقتحموا ليصعدوا إلى الرب لئلا يبطش بهم».","19:25":"فانحدر موسى إلى الشعب وقال لهم.","20:1":"ثم تكلم الله بجميع هذه الكلمات قائلا:","20:2":"«أنا الرب إلهك الذي أخرجك من أرض مصر من بيت العبودية.","20:3":"لا يكن لك آلهة أخرى أمامي.","20:4":"لا تصنع لك تمثالا منحوتا, ولا صورة ما مما في السماء من فوق, وما في الأرض من تحت, وما في الماء من تحت الأرض.","20:5":"لا تسجد لهن ولا تعبدهن, لأني أنا الرب إلهك إله غيور, أفتقد ذنوب الآباء في الأبناء في الجيل الثالث والرابع من مبغضي,","20:6":"وأصنع إحسانا إلى ألوف من محبي وحافظي وصاياي.","20:7":"لا تنطق باسم الرب إلهك باطلا, لأن الرب لا يبرئ من نطق باسمه باطلا.","20:8":"اذكر يوم السبت لتقدسه.","20:9":"ستة أيام تعمل وتصنع جميع عملك,","20:10":"وأما اليوم السابع ففيه سبت للرب إلهك. لا تصنع عملا ما أنت وابنك وابنتك وعبدك وأمتك وبهيمتك ونزيلك الذي داخل أبوابك.","20:11":"لأن في ستة أيام صنع الرب السماء والأرض والبحر وكل ما فيها, واستراح في اليوم السابع. لذلك بارك الرب يوم السبت وقدسه.","20:12":"أكرم أباك وأمك لكي تطول أيامك على الأرض التي يعطيك الرب إلهك.","20:13":"لا تقتل.","20:14":"لا تزن.","20:15":"لا تسرق.","20:16":"لا تشهد على قريبك شهادة زور.","20:17":"لا تشته بيت قريبك. لا تشته امرأة قريبك, ولا عبده, ولا أمته, ولا ثوره, ولا حماره, ولا شيئا مما لقريبك».","20:18":"وكان جميع الشعب يرون الرعود والبروق وصوت البوق, والجبل يدخن. ولما رأى الشعب ارتعدوا ووقفوا من بعيد,","20:19":"وقالوا لموسى: «تكلم أنت معنا فنسمع. ولا يتكلم معنا الله لئلا نموت».","20:20":"فقال موسى للشعب: «لا تخافوا. لأن الله إنما جاء لكي يمتحنكم, ولكي تكون مخافته أمام وجوهكم حتى لا تخطئوا».","20:21":"فوقف الشعب من بعيد, وأما موسى فاقترب إلى الضباب حيث كان الله.","20:22":"فقال الرب لموسى: «هكذا تقول لبني إسرائيل: أنتم رأيتم أنني من السماء تكلمت معكم.","20:23":"لا تصنعوا معي آلهة فضة, ولا تصنعوا لكم آلهة ذهب.","20:24":"مذبحا من تراب تصنع لي وتذبح عليه محرقاتك وذبائح سلامتك, غنمك وبقرك. في كل الأماكن التي فيها أصنع لاسمي ذكرا آتي إليك وأباركك.","20:25":"وإن صنعت لي مذبحا من حجارة فلا تبنه منها منحوتة. إذا رفعت عليها إزميلك تدنسها.","20:26":"ولا تصعد بدرج إلى مذبحي كيلا تنكشف عورتك عليه.","21:1":"«وهذه هي الأحكام التي تضع أمامهم:","21:2":"إذا اشتريت عبدا عبرانيا, فست سنين يخدم, وفي السابعة يخرج حرا مجانا.","21:3":"إن دخل وحده فوحده يخرج. إن كان بعل امرأة, تخرج امرأته معه.","21:4":"إن أعطاه سيده امرأة وولدت له بنين أو بنات, فالمرأة وأولادها يكونون لسيده, وهو يخرج وحده.","21:5":"ولكن إن قال العبد: أحب سيدي وامرأتي وأولادي, لا أخرج حرا,","21:6":"يقدمه سيده إلى الله, ويقربه إلى الباب أو إلى القائمة, ويثقب سيده أذنه بالمثقب, فيخدمه إلى الأبد.","21:7":"وإذا باع رجل ابنته أمة, لا تخرج كما يخرج العبيد.","21:8":"إن قبحت في عيني سيدها الذي خطبها لنفسه, يدعها تفك. وليس له سلطان أن يبيعها لقوم أجانب لغدره بها.","21:9":"وإن خطبها لابنه فبحسب حق البنات يفعل لها.","21:10":"إن اتخذ لنفسه أخرى, لا ينقص طعامها وكسوتها ومعاشرتها.","21:11":"وإن لم يفعل لها هذه الثلاث تخرج مجانا بلا ثمن.","21:12":"«من ضرب إنسانا فمات يقتل قتلا.","21:13":"ولكن الذي لم يتعمد, بل أوقع الله في يده, فأنا أجعل لك مكانا يهرب إليه.","21:14":"وإذا بغى إنسان على صاحبه ليقتله بغدر فمن عند مذبحي تأخذه للموت.","21:15":"ومن ضرب أباه أو أمه يقتل قتلا.","21:16":"ومن سرق إنسانا وباعه, أو وجد في يده, يقتل قتلا.","21:17":"ومن شتم أباه أو أمه يقتل قتلا.","21:18":"وإذا تخاصم رجلان فضرب أحدهما الآخر بحجر أو بلكمة ولم يقتل بل سقط في الفراش,","21:19":"فإن قام وتمشى خارجا على عكازه يكون الضارب بريئا. إلا أنه يعوض عطلته, وينفق على شفائه.","21:20":"وإذا ضرب إنسان عبده أو أمته بالعصا فمات تحت يده ينتقم منه.","21:21":"لكن إن بقي يوما أو يومين لا ينتقم منه لأنه ماله.","21:22":"وإذا تخاصم رجال وصدموا امرأة حبلى فسقط ولدها ولم تحصل أذية, يغرم كما يضع عليه زوج المرأة, ويدفع عن يد القضاة.","21:23":"وإن حصلت أذية تعطي نفسا بنفس,","21:24":"وعينا بعين, وسنا بسن, ويدا بيد, ورجلا برجل,","21:25":"وكيا بكي, وجرحا بجرح, ورضا برض.","21:26":"وإذا ضرب إنسان عين عبده, أو عين أمته فأتلفها, يطلقه حرا عوضا عن عينه.","21:27":"وإن أسقط سن عبده أو سن أمته يطلقه حرا عوضا عن سنه.","21:28":"«وإذا نطح ثور رجلا أو امرأة فمات, يرجم الثور ولا يؤكل لحمه. وأما صاحب الثور فيكون بريئا.","21:29":"ولكن إن كان ثورا نطاحا من قبل, وقد أشهد على صاحبه ولم يضبطه, فقتل رجلا أو امرأة, فالثور يرجم وصاحبه أيضا يقتل.","21:30":"إن وضعت عليه فدية, يدفع فداء نفسه كل ما يوضع عليه.","21:31":"أو إذا نطح ابنا أو نطح ابنة فبحسب هذا الحكم يفعل به.","21:32":"إن نطح الثور عبدا أو أمة, يعطي سيده ثلاثين شاقل فضة, والثور يرجم.","21:33":"وإذا فتح إنسان بئرا, أو حفر إنسان بئرا ولم يغطه, فوقع فيه ثور أو حمار,","21:34":"فصاحب البئر يعوض ويرد فضة لصاحبه, والميت يكون له.","21:35":"وإذا نطح ثور إنسان ثور صاحبه فمات, يبيعان الثور الحي ويقتسمان ثمنه. والميت أيضا يقتسمانه.","21:36":"لكن إذا علم أنه ثور نطاح من قبل ولم يضبطه صاحبه, يعوض عن الثور بثور, والميت يكون له.","22:1":"«إذا سرق إنسان ثورا أو شاة فذبحه أو باعه, يعوض عن الثور بخمسة ثيران, وعن الشاة بأربعة من الغنم.","22:2":"إن وجد السارق وهو ينقب, فضرب ومات, فليس له دم.","22:3":"ولكن إن أشرقت عليه الشمس, فله دم. إنه يعوض. إن لم يكن له يبع بسرقته.","22:4":"إن وجدت السرقة في يده حية, ثورا كانت أم حمارا أم شاة, يعوض باثنين.","22:5":"«إذا رعى إنسان حقلا أو كرما وسرح مواشيه فرعت في حقل غيره, فمن أجود حقله, وأجود كرمه يعوض.","22:6":"إذا خرجت نار وأصابت شوكا فاحترقت أكداس أو زرع أو حقل, فالذي أوقد الوقيد يعوض.","22:7":"إذا أعطى إنسان صاحبه فضة أو أمتعة للحفظ, فسرقت من بيت الإنسان, فإن وجد السارق, يعوض باثنين.","22:8":"وإن لم يوجد السارق يقدم صاحب البيت إلى الله ليحكم هل لم يمد يده إلى ملك صاحبه.","22:9":"في كل دعوى جناية, من جهة ثور أو حمار أو شاة أو ثوب أو مفقود ما, يقال: إن هذا هو, تقدم إلى الله دعواهما. فالذي يحكم الله بذنبه, يعوض صاحبه باثنين.","22:10":"إذا أعطى إنسان صاحبه حمارا أو ثورا أو شاة أو بهيمة ما للحفظ, فمات أو انكسر أو نهب وليس ناظر,","22:11":"فيمين الرب تكون بينهما, هل لم يمد يده إلى ملك صاحبه. فيقبل صاحبه. فلا يعوض.","22:12":"وإن سرق من عنده يعوض صاحبه.","22:13":"إن افترس يحضره شهادة. لا يعوض عن المفترس.","22:14":"وإذا استعار إنسان من صاحبه شيئا فانكسر أو مات, وصاحبه ليس معه, يعوض.","22:15":"وإن كان صاحبه معه لا يعوض. إن كان مستأجرا أتى بأجرته.","22:16":"«وإذا راود رجل عذراء لم تخطب, فاضطجع معها يمهرها لنفسه زوجة.","22:17":"إن أبى أبوها أن يعطيه إياها, يزن له فضة كمهر العذارى.","22:18":"لا تدع ساحرة تعيش.","22:19":"كل من اضطجع مع بهيمة يقتل قتلا.","22:20":"من ذبح لآلهة غير الرب وحده, يهلك.","22:21":"«ولا تضطهد الغريب ولا تضايقه, لأنكم كنتم غرباء في أرض مصر.","22:22":"لا تسيء إلى أرملة ما ولا يتيم.","22:23":"إن أسأت إليه فإني إن صرخ إلي أسمع صراخه,","22:24":"فيحمى غضبي وأقتلكم بالسيف, فتصير نساؤكم أرامل, وأولادكم يتامى.","22:25":"إن أقرضت فضة لشعبي الفقير الذي عندك فلا تكن له كالمرابي. لا تضعوا عليه ربا.","22:26":"إن ارتهنت ثوب صاحبك فإلى غروب الشمس ترده له,","22:27":"لأنه وحده غطاؤه, هو ثوبه لجلده, في ماذا ينام؟ فيكون إذا صرخ إلي أني أسمع, لأني رؤوف.","22:28":"«لا تسب الله, ولا تلعن رئيسا في شعبك.","22:29":"لا تؤخر ملء بيدرك, وقطر معصرتك, وأبكار بنيك تعطيني.","22:30":"كذلك تفعل ببقرك وغنمك. سبعة أيام يكون مع أمه, وفي اليوم الثامن تعطيني إياه.","22:31":"وتكونون لي أناسا مقدسين. ولحم فريسة في الصحراء لا تأكلوا. للكلاب تطرحونه.","23:1":"«لا تقبل خبرا كاذبا, ولا تضع يدك مع المنافق لتكون شاهد ظلم.","23:2":"لا تتبع الكثيرين إلى فعل الشر, ولا تجب في دعوى مائلا وراء الكثيرين للتحريف.","23:3":"ولا تحاب مع المسكين في دعواه.","23:4":"إذا صادفت ثور عدوك أو حماره شاردا, ترده إليه.","23:5":"إذا رأيت حمار مبغضك واقعا تحت حمله وعدلت عن حله, فلا بد أن تحل معه.","23:6":"لا تحرف حق فقيرك في دعواه.","23:7":"ابتعد عن كلام الكذب, ولا تقتل البريء والبار, لأني لا أبرر المذنب.","23:8":"ولا تأخذ رشوة, لأن الرشوة تعمي المبصرين, وتعوج كلام الأبرار.","23:9":"ولا تضايق الغريب فإنكم عارفون نفس الغريب, لأنكم كنتم غرباء في أرض مصر.","23:10":"«وست سنين تزرع أرضك وتجمع غلتها,","23:11":"وأما في السابعة فتريحها وتتركها ليأكل فقراء شعبك. وفضلتهم تأكلها وحوش البرية. كذلك تفعل بكرمك وزيتونك.","23:12":"ستة أيام تعمل عملك. وأما اليوم السابع ففيه تستريح, لكي يستريح ثورك وحمارك, ويتنفس ابن أمتك والغريب.","23:13":"وكل ما قلت لكم احتفظوا به, ولا تذكروا اسم آلهة أخرى, ولا يسمع من فمك.","23:14":"«ثلاث مرات تعيد لي في السنة.","23:15":"تحفظ عيد الفطير. تأكل فطيرا سبعة أيام كما أمرتك في وقت شهر أبيب, لأنه فيه خرجت من مصر. ولا يظهروا أمامي فارغين.","23:16":"وعيد الحصاد أبكار غلاتك التي تزرع في الحقل. وعيد الجمع في نهاية السنة عندما تجمع غلاتك من الحقل.","23:17":"ثلاث مرات في السنة يظهر جميع ذكورك أمام السيد الرب.","23:18":"لا تذبح على خمير دم ذبيحتي, ولا يبت شحم عيدي إلى الغد.","23:19":"أول أبكار أرضك تحضره إلى بيت الرب إلهك. لا تطبخ جديا بلبن أمه.","23:20":"«ها أنا مرسل ملاكا أمام وجهك ليحفظك في الطريق, وليجيء بك إلى المكان الذي أعددته.","23:21":"احترز منه واسمع لصوته ولا تتمرد عليه, لأنه لا يصفح عن ذنوبكم, لأن اسمي فيه.","23:22":"ولكن إن سمعت لصوته وفعلت كل ما أتكلم به, أعادي أعداءك, وأضايق مضايقيك.","23:23":"فإن ملاكي يسير أمامك ويجيء بك إلى الأموريين والحثيين والفرزيين والكنعانيين والحويين واليبوسيين, فأبيدهم.","23:24":"لا تسجد لآلهتهم, ولا تعبدها, ولا تعمل كأعمالهم, بل تبيدهم وتكسر أنصابهم.","23:25":"وتعبدون الرب إلهكم, فيبارك خبزك وماءك, وأزيل المرض من بينكم.","23:26":"لا تكون مسقطة ولا عاقر في أرضك, وأكمل عدد أيامك.","23:27":"أرسل هيبتي أمامك, وأزعج جميع الشعوب الذين تأتي عليهم, وأعطيك جميع أعدائك مدبرين.","23:28":"وأرسل أمامك الزنابير. فتطرد الحويين والكنعانيين والحثيين من أمامك.","23:29":"لا أطردهم من أمامك في سنة واحدة, لئلا تصير الأرض خربة, فتكثر عليك وحوش البرية.","23:30":"قليلا قليلا أطردهم من أمامك إلى أن تثمر وتملك الأرض.","23:31":"وأجعل تخومك من بحر سوف إلى بحر فلسطين, ومن البرية إلى النهر. فإني أدفع إلى أيديكم سكان الأرض, فتطردهم من أمامك.","23:32":"لا تقطع معهم ولا مع آلهتهم عهدا.","23:33":"لا يسكنوا في أرضك لئلا يجعلوك تخطئ إلي. إذا عبدت آلهتهم فإنه يكون لك فخا».","24:1":"وقال لموسى: «اصعد إلى الرب أنت وهارون وناداب وأبيهو, وسبعون من شيوخ إسرائيل, واسجدوا من بعيد.","24:2":"ويقترب موسى وحده إلى الرب, وهم لا يقتربون. وأما الشعب فلا يصعد معه».","24:3":"فجاء موسى وحدث الشعب بجميع أقوال الرب وجميع الأحكام, فأجاب جميع الشعب بصوت واحد وقالوا: «كل الأقوال التي تكلم بها الرب نفعل».","24:4":"فكتب موسى جميع أقوال الرب. وبكر في الصباح وبنى مذبحا في أسفل الجبل, واثني عشر عمودا لأسباط إسرائيل الاثني عشر.","24:5":"وأرسل فتيان بني إسرائيل, فأصعدوا محرقات, وذبحوا ذبائح سلامة للرب من الثيران.","24:6":"فأخذ موسى نصف الدم ووضعه في الطسوس. ونصف الدم رشه على المذبح.","24:7":"وأخذ كتاب العهد وقرأ في مسامع الشعب, فقالوا: «كل ما تكلم به الرب نفعل ونسمع له».","24:8":"وأخذ موسى الدم ورش على الشعب وقال: «هوذا دم العهد الذي قطعه الرب معكم على جميع هذه الأقوال».","24:9":"ثم صعد موسى وهارون وناداب وأبيهو وسبعون من شيوخ إسرائيل,","24:10":"ورأوا إله إسرائيل, وتحت رجليه شبه صنعة من العقيق الأزرق الشفاف, وكذات السماء في النقاوة.","24:11":"ولكنه لم يمد يده إلى أشراف بني إسرائيل. فرأوا الله وأكلوا وشربوا.","24:12":"وقال الرب لموسى: «اصعد إلي إلى الجبل, وكن هناك, فأعطيك لوحي الحجارة والشريعة والوصية التي كتبتها لتعليمهم».","24:13":"فقام موسى ويشوع خادمه. وصعد موسى إلى جبل الله.","24:14":"وأما الشيوخ فقال لهم: «اجلسوا لنا ههنا حتى نرجع إليكم. وهوذا هارون وحور معكم. فمن كان صاحب دعوى فليتقدم إليهما».","24:15":"فصعد موسى إلى الجبل, فغطى السحاب الجبل,","24:16":"وحل مجد الرب على جبل سيناء, وغطاه السحاب ستة أيام. وفي اليوم السابع دعي موسى من وسط السحاب.","24:17":"وكان منظر مجد الرب كنار آكلة على رأس الجبل أمام عيون بني إسرائيل.","24:18":"ودخل موسى في وسط السحاب وصعد إلى الجبل. وكان موسى في الجبل أربعين نهارا وأربعين ليلة.","25:1":"وكلم الرب موسى قائلا:","25:2":"«كلم بني إسرائيل أن يأخذوا لي تقدمة. من كل من يحثه قلبه تأخذون تقدمتي.","25:3":"وهذه هي التقدمة التي تأخذونها منهم: ذهب وفضة ونحاس,","25:4":"وأسمانجوني وأرجوان وقرمز وبوص وشعر معزى,","25:5":"وجلود كباش محمرة وجلود تخس وخشب سنط,","25:6":"وزيت للمنارة وأطياب لدهن المسحة وللبخور العطر,","25:7":"وحجارة جزع وحجارة ترصيع للرداء والصدرة.","25:8":"فيصنعون لي مقدسا لأسكن في وسطهم.","25:9":"بحسب جميع ما أنا أريك من مثال المسكن, ومثال جميع آنيته هكذا تصنعون.","25:10":"«فيصنعون تابوتا من خشب السنط, طوله ذراعان ونصف, وعرضه ذراع ونصف, وارتفاعه ذراع ونصف.","25:11":"وتغشيه بذهب نقي. من داخل ومن خارج تغشيه, وتصنع عليه إكليلا من ذهب حواليه.","25:12":"وتسبك له أربع حلقات من ذهب, وتجعلها على قوائمه الأربع. على جانبه الواحد حلقتان, وعلى جانبه الثاني حلقتان.","25:13":"وتصنع عصوين من خشب السنط وتغشيهما بذهب.","25:14":"وتدخل العصوين في الحلقات على جانبي التابوت ليحمل التابوت بهما.","25:15":"تبقى العصوان في حلقات التابوت. لا تنزعان منها.","25:16":"وتضع في التابوت الشهادة التي أعطيك.","25:17":"«وتصنع غطاء من ذهب نقي طوله ذراعان ونصف, وعرضه ذراع ونصف,","25:18":"وتصنع كروبين من ذهب. صنعة خراطة تصنعهما على طرفي الغطاء.","25:19":"فاصنع كروبا واحدا على الطرف من هنا, وكروبا آخر على الطرف من هناك. من الغطاء تصنعون الكروبين على طرفيه.","25:20":"ويكون الكروبان باسطين أجنحتهما إلى فوق, مظللين بأجنحتهما على الغطاء, ووجهاهما كل واحد إلى الآخر. نحو الغطاء يكون وجها الكروبين.","25:21":"وتجعل الغطاء على التابوت من فوق, وفي التابوت تضع الشهادة التي أعطيك.","25:22":"وأنا أجتمع بك هناك وأتكلم معك, من على الغطاء من بين الكروبين اللذين على تابوت الشهادة, بكل ما أوصيك به إلى بني إسرائيل.","25:23":"«وتصنع مائدة من خشب السنط طولها ذراعان, وعرضها ذراع, وارتفاعها ذراع ونصف.","25:24":"وتغشيها بذهب نقي, وتصنع لها إكليلا من ذهب حواليها.","25:25":"وتصنع لها حاجبا على شبر حواليها, وتصنع لحاجبها إكليلا من ذهب حواليها.","25:26":"وتصنع لها أربع حلقات من ذهب, وتجعل الحلقات على الزوايا الأربع التي لقوائمها الأربع.","25:27":"عند الحاجب تكون الحلقات بيوتا لعصوين لحمل المائدة.","25:28":"وتصنع العصوين من خشب السنط وتغشيهما بذهب, فتحمل بهما المائدة.","25:29":"وتصنع صحافها وصحونها وكأساتها وجاماتها التي يسكب بها. من ذهب نقي تصنعها.","25:30":"وتجعل على المائدة خبز الوجوه أمامي دائما.","25:31":"«وتصنع منارة من ذهب نقي. عمل الخراطة تصنع المنارة, قاعدتها وساقها. تكون كأساتها وعجرها وأزهارها منها.","25:32":"وست شعب خارجة من جانبيها. من جانبها الواحد ثلاث شعب منارة, ومن جانبها الثاني ثلاث شعب منارة.","25:33":"في الشعبة الواحدة ثلاث كأسات لوزية بعجرة وزهر, وفي الشعبة الثانية ثلاث كأسات لوزية بعجرة وزهر, وهكذا إلى الست الشعب الخارجة من المنارة.","25:34":"وفي المنارة أربع كأسات لوزية بعجرها وأزهارها.","25:35":"وتحت الشعبتين منها عجرة, وتحت الشعبتين منها عجرة, وتحت الشعبتين منها عجرة إلى الست الشعب الخارجة من المنارة.","25:36":"تكون عجرها وشعبها منها. جميعها خراطة واحدة من ذهب نقي.","25:37":"وتصنع سرجها سبعة, فتصعد سرجها لتضيء إلى مقابلها.","25:38":"وملاقطها ومنافضها من ذهب نقي.","25:39":"من وزنة ذهب نقي تصنع مع جميع هذه الأواني.","25:40":"وانظر فاصنعها على مثالها الذي أظهر لك في الجبل.","26:1":"«وأما المسكن فتصنعه من عشر شقق بوص مبروم وأسمانجوني وأرجوان وقرمز. بكروبيم صنعة حائك حاذق تصنعها.","26:2":"طول الشقة الواحدة ثمان وعشرون ذراعا, وعرض الشقة الواحدة أربع أذرع. قياسا واحدا لجميع الشقق.","26:3":"تكون خمس من الشقق بعضها موصول ببعض, وخمس شقق بعضها موصول ببعض.","26:4":"وتصنع عرى من أسمانجوني على حاشية الشقة الواحدة في الطرف من الموصل الواحد. وكذلك تصنع في حاشية الشقة الطرفية من الموصل الثاني.","26:5":"خمسين عروة تصنع في الشقة الواحدة, وخمسين عروة تصنع في طرف الشقة الذي في الموصل الثاني. تكون العرى بعضها مقابل لبعض.","26:6":"وتصنع خمسين شظاظا من ذهب, وتصل الشقتين بعضهما ببعض بالأشظة. فيصير المسكن واحدا.","26:7":"«وتصنع شققا من شعر معزى خيمة على المسكن. إحدى عشرة شقة تصنعها.","26:8":"طول الشقة الواحدة ثلاثون ذراعا, وعرض الشقة الواحدة أربع أذرع. قياسا واحدا للإحدى عشرة شقة.","26:9":"وتصل خمسا من الشقق وحدها, وستا من الشقق وحدها. وتثني الشقة السادسة في وجه الخيمة.","26:10":"وتصنع خمسين عروة على حاشية الشقة الواحدة الطرفية من الموصل الواحد, وخمسين عروة على حاشية الشقة من الموصل الثاني.","26:11":"وتصنع خمسين شظاظا من نحاس, وتدخل الأشظة في العرى, وتصل الخيمة فتصير واحدة.","26:12":"وأما المدلى الفاضل من شقق الخيمة, نصف الشقة الموصلة الفاضل, فيدلى على مؤخر المسكن.","26:13":"والذراع من هنا والذراع من هناك, من الفاضل في طول شقق الخيمة, تكونان مدلاتين على جانبي المسكن من هنا ومن هناك لتغطيته.","26:14":"وتصنع غطاء للخيمة من جلود كباش محمرة, وغطاء من جلود تخس من فوق.","26:15":"«وتصنع الألواح للمسكن من خشب السنط قائمة.","26:16":"طول اللوح عشر أذرع, وعرض اللوح الواحد ذراع ونصف.","26:17":"وللوح الواحد رجلان مقرونة إحداهما بالأخرى. هكذا تصنع لجميع ألواح المسكن.","26:18":"وتصنع الألواح للمسكن عشرين لوحا إلى جهة الجنوب نحو التيمن.","26:19":"وتصنع أربعين قاعدة من فضة تحت العشرين لوحا. تحت اللوح الواحد قاعدتان لرجليه, وتحت اللوح الواحد قاعدتان لرجليه.","26:20":"ولجانب المسكن الثاني إلى جهة الشمال عشرين لوحا.","26:21":"وأربعين قاعدة لها من فضة. تحت اللوح الواحد قاعدتان, وتحت اللوح الواحد قاعدتان.","26:22":"ولمؤخر المسكن نحو الغرب تصنع ستة ألواح.","26:23":"وتصنع لوحين لزاويتي المسكن في المؤخر,","26:24":"ويكونان مزدوجين من أسفل. وعلى سواء يكونان مزدوجين إلى رأسه إلى الحلقة الواحدة. هكذا يكون لكليهما. يكونان للزاويتين.","26:25":"فتكون ثمانية ألواح, وقواعدها من فضة ست عشرة قاعدة. تحت اللوح الواحد قاعدتان, وتحت اللوح الواحد قاعدتان.","26:26":"«وتصنع عوارض من خشب السنط, خمسا لألواح جانب المسكن الواحد,","26:27":"وخمس عوارض لألواح جانب المسكن الثاني, وخمس عوارض لألواح جانب المسكن في المؤخر نحو الغرب.","26:28":"والعارضة الوسطى في وسط الألواح تنفذ من الطرف إلى الطرف.","26:29":"وتغشي الألواح بذهب, وتصنع حلقاتها من ذهب بيوتا للعوارض, وتغشي العوارض بذهب.","26:30":"وتقيم المسكن كرسمه الذي أظهر لك في الجبل.","26:31":"«وتصنع حجابا من أسمانجوني وأرجوان وقرمز وبوص مبروم. صنعة حائك حاذق يصنعه بكروبيم.","26:32":"وتجعله على أربعة أعمدة من سنط مغشاة بذهب. رززها من ذهب. على أربع قواعد من فضة.","26:33":"وتجعل الحجاب تحت الأشظة. وتدخل إلى هناك داخل الحجاب تابوت الشهادة, فيفصل لكم الحجاب بين القدس وقدس الأقداس.","26:34":"وتجعل الغطاء على تابوت الشهادة في قدس الأقداس.","26:35":"وتضع المائدة خارج الحجاب, والمنارة مقابل المائدة على جانب المسكن نحو التيمن, وتجعل المائدة على جانب الشمال.","26:36":"«وتصنع سجفا لمدخل الخيمة من أسمانجوني وأرجوان وقرمز وبوص مبروم صنعة الطراز.","26:37":"وتصنع للسجف خمسة أعمدة من سنط وتغشيها بذهب. رززها من ذهب, وتسبك لها خمس قواعد من نحاس.","27:1":"«وتصنع المذبح من خشب السنط, طوله خمس أذرع, وعرضه خمس أذرع. مربعا يكون المذبح. وارتفاعه ثلاث أذرع.","27:2":"وتصنع قرونه على زواياه الأربع. منه تكون قرونه, وتغشيه بنحاس.","27:3":"وتصنع قدوره لرفع رماده, ورفوشه ومراكنه ومناشله ومجامره. جميع آنيته تصنعها من نحاس.","27:4":"وتصنع له شباكة صنعة الشبكة من نحاس, وتصنع على الشبكة أربع حلقات من نحاس على أربعة أطرافه.","27:5":"وتجعلها تحت حاجب المذبح من أسفل, وتكون الشبكة إلى نصف المذبح.","27:6":"وتصنع عصوين للمذبح, عصوين من خشب السنط وتغشيهما بنحاس.","27:7":"وتدخل عصواه في الحلقات, فتكون العصوان على جانبي المذبح حينما يحمل.","27:8":"مجوفا تصنعه من ألواح, كما أظهر لك في الجبل هكذا يصنعونه.","27:9":"«وتصنع دار المسكن. إلى جهة الجنوب نحو التيمن للدار أستار من بوص مبروم مئة ذراع طولا إلى الجهة الواحدة.","27:10":"وأعمدتها عشرون, وقواعدها عشرون من نحاس. رزز الأعمدة وقضبانها من فضة.","27:11":"وكذلك إلى جهة الشمال في الطول أستار مئة ذراع طولا. وأعمدتها عشرون, وقواعدها عشرون من نحاس. رزز الأعمدة وقضبانها من فضة.","27:12":"وفي عرض الدار إلى جهة الغرب أستار خمسون ذراعا. أعمدتها عشرة, وقواعدها عشر.","27:13":"وعرض الدار إلى جهة الشرق نحو الشروق خمسون ذراعا.","27:14":"وخمس عشرة ذراعا من الأستار للجانب الواحد. أعمدتها ثلاثة وقواعدها ثلاث.","27:15":"وللجانب الثاني خمس عشرة ذراعا من الأستار. أعمدتها ثلاثة وقواعدها ثلاث.","27:16":"ولباب الدار سجف عشرون ذراعا من أسمانجوني وأرجوان وقرمز وبوص مبروم صنعة الطراز. أعمدته أربعة, وقواعدها أربع.","27:17":"لكل أعمدة الدار حواليها قضبان من فضة. رززها من فضة, وقواعدها من نحاس.","27:18":"طول الدار مئة ذراع, وعرضها خمسون فخمسون, وارتفاعها خمس أذرع من بوص مبروم, وقواعدها من نحاس.","27:19":"جميع أواني المسكن في كل خدمته وجميع أوتاده وجميع أوتاد الدار من نحاس.","27:20":"«وأنت تأمر بني إسرائيل أن يقدموا إليك زيت زيتون مرضوض نقيا للضوء لإصعاد السرج دائما.","27:21":"في خيمة الاجتماع, خارج الحجاب الذي أمام الشهادة, يرتبها هارون وبنوه من المساء إلى الصباح أمام الرب. فريضة دهرية في أجيالهم من بني إسرائيل.","28:1":"«وقرب إليك هارون أخاك وبنيه معه من بين بني إسرائيل ليكهن لي. هارون ناداب وأبيهو ألعازار وإيثامار بني هارون.","28:2":"واصنع ثيابا مقدسة لهارون أخيك للمجد والبهاء.","28:3":"وتكلم جميع حكماء القلوب الذين ملأتهم روح حكمة, أن يصنعوا ثياب هارون لتقديسه ليكهن لي.","28:4":"وهذه هي الثياب التي يصنعونها: صدرة ورداء وجبة وقميص مخرم وعمامة ومنطقة. فيصنعون ثيابا مقدسة لهارون أخيك ولبنيه ليكهن لي.","28:5":"وهم يأخذون الذهب والأسمانجوني والأرجوان والقرمز والبوص.","28:6":"«فيصنعون الرداء من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم صنعة حائك حاذق.","28:7":"يكون له كتفان موصولان في طرفيه ليتصل.","28:8":"وزنار شده الذي عليه يكون منه كصنعته. من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم.","28:9":"وتأخذ حجري جزع وتنقش عليهما أسماء بني إسرائيل.","28:10":"ستة من أسمائهم على الحجر الواحد, وأسماء الستة الباقين على الحجر الثاني حسب مواليدهم.","28:11":"صنعة نقاش الحجارة نقش الخاتم تنقش الحجرين على حسب أسماء بني إسرائيل. محاطين بطوقين من ذهب تصنعهما.","28:12":"وتضع الحجرين على كتفي الرداء حجري تذكار لبني إسرائيل. فيحمل هارون أسماءهم أمام الرب على كتفيه للتذكار.","28:13":"وتصنع طوقين من ذهب,","28:14":"وسلسلتين من ذهب نقي. مجدولتين تصنعهما صنعة الضفر, وتجعل سلسلتي الضفائر في الطوقين.","28:15":"«وتصنع صدرة قضاء. صنعة حائك حاذق كصنعة الرداء تصنعها. من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم تصنعها.","28:16":"تكون مربعة مثنية, طولها شبر وعرضها شبر.","28:17":"وترصع فيها ترصيع حجر أربعة صفوف حجارة. صف: عقيق أحمر وياقوت أصفر وزمرد, الصف الأول.","28:18":"والصف الثاني: بهرمان وياقوت أزرق وعقيق أبيض.","28:19":"والصف الثالث: عين الهر ويشم وجمشت.","28:20":"والصف الرابع: زبرجد وجزع ويشب. تكون مطوقة بذهب في ترصيعها.","28:21":"وتكون الحجارة على أسماء بني إسرائيل, اثني عشر على أسمائهم. كنقش الخاتم كل واحد على اسمه تكون للاثني عشر سبطا.","28:22":"«وتصنع على الصدرة سلاسل مجدولة صنعة الضفر من ذهب نقي.","28:23":"وتصنع على الصدرة حلقتين من ذهب, وتجعل الحلقتين على طرفي الصدرة.","28:24":"وتجعل ضفيرتي الذهب في الحلقتين على طرفي الصدرة.","28:25":"وتجعل طرفي الضفيرتين الآخرين في الطوقين, وتجعلهما على كتفي الرداء إلى قدامه.","28:26":"وتصنع حلقتين من ذهب وتضعهما على طرفي الصدرة على حاشيتها التي إلى جهة الرداء من داخل.","28:27":"وتصنع حلقتين من ذهب, وتجعلهما على كتفي الرداء من أسفل من قدامه عند وصله من فوق زنار الرداء.","28:28":"ويربطون الصدرة بحلقتيها إلى حلقتي الرداء بخيط من أسمانجوني لتكون على زنار الرداء, ولا تنزع الصدرة عن الرداء.","28:29":"فيحمل هارون أسماء بني إسرائيل في صدرة القضاء على قلبه عند دخوله إلى القدس للتذكار أمام الرب دائما.","28:30":"وتجعل في صدرة القضاء الأوريم والتميم لتكون على قلب هارون عند دخوله أمام الرب. فيحمل هارون قضاء بني إسرائيل على قلبه أمام الرب دائما.","28:31":"«وتصنع جبة الرداء كلها من أسمانجوني,","28:32":"وتكون فتحة رأسها في وسطها, ويكون لفتحتها حاشية حواليها صنعة الحائك. كفتحة الدرع يكون لها. لا تشق.","28:33":"وتصنع على أذيالها رمانات من أسمانجوني وأرجوان وقرمز, على أذيالها حواليها, وجلاجل من ذهب بينها حواليها.","28:34":"جلجل ذهب ورمانة, جلجل ذهب ورمانة, على أذيال الجبة حواليها.","28:35":"فتكون على هارون للخدمة ليسمع صوتها عند دخوله إلى القدس أمام الرب, وعند خروجه, لئلا يموت.","28:36":"«وتصنع صفيحة من ذهب نقي, وتنقش عليها نقش خاتم: «قدس للرب».","28:37":"وتضعها على خيط أسمانجوني لتكون على العمامة. إلى قدام العمامة تكون.","28:38":"فتكون على جبهة هارون, فيحمل هارون إثم الأقداس التي يقدسها بنو إسرائيل, جميع عطايا أقداسهم. وتكون على جبهته دائما للرضا عنهم أمام الرب.","28:39":"وتخرم القميص من بوص, وتصنع العمامة من بوص, والمنطقة تصنعها صنعة الطراز.","28:40":"«ولبني هارون تصنع أقمصة, وتصنع لهم مناطق, وتصنع لهم قلانس للمجد والبهاء.","28:41":"وتلبس هارون أخاك إياها وبنيه معه, وتمسحهم, وتملأ أياديهم, وتقدسهم ليكهنوا لي.","28:42":"وتصنع لهم سراويل من كتان لستر العورة. من الحقوين إلى الفخذين تكون.","28:43":"فتكون على هارون وبنيه عند دخولهم إلى خيمة الاجتماع, أو عند اقترابهم إلى المذبح للخدمة في القدس, لئلا يحملوا إثما ويموتوا. فريضة أبدية له ولنسله من بعده.","29:1":"«وهذا ما تصنعه لهم لتقديسهم ليكهنوا لي: خذ ثورا واحدا ابن بقر, وكبشين صحيحين,","29:2":"وخبز فطير, وأقراص فطير ملتوتة بزيت, ورقاق فطير مدهونة بزيت. من دقيق حنطة تصنعها.","29:3":"وتجعلها في سلة واحدة, وتقدمها في السلة مع الثور والكبشين.","29:4":"«وتقدم هارون وبنيه إلى باب خيمة الاجتماع وتغسلهم بماء.","29:5":"وتأخذ الثياب وتلبس هارون القميص وجبة الرداء والرداء والصدرة, وتشده بزنار الرداء,","29:6":"وتضع العمامة على رأسه, وتجعل الإكليل المقدس على العمامة,","29:7":"وتأخذ دهن المسحة وتسكبه على رأسه وتمسحه.","29:8":"وتقدم بنيه وتلبسهم أقمصة.","29:9":"وتنطقهم بمناطق, هارون وبنيه, وتشد لهم قلانس. فيكون لهم كهنوت فريضة أبدية. وتملأ يد هارون وأيدي بنيه.","29:10":"«وتقدم الثور إلى قدام خيمة الاجتماع, فيضع هارون وبنوه أيديهم على رأس الثور.","29:11":"فتذبح الثور أمام الرب عند باب خيمة الاجتماع.","29:12":"وتأخذ من دم الثور وتجعله على قرون المذبح بإصبعك, وسائر الدم تصبه إلى أسفل المذبح.","29:13":"وتأخذ كل الشحم الذي يغشي الجوف, وزيادة الكبد والكليتين والشحم الذي عليهما, وتوقدها على المذبح.","29:14":"وأما لحم الثور وجلده وفرثه فتحرقها بنار خارج المحلة. هو ذبيحة خطية.","29:15":"«وتأخذ الكبش الواحد, فيضع هارون وبنوه أيديهم على رأس الكبش.","29:16":"فتذبح الكبش وتأخذ دمه وترشه على المذبح من كل ناحية.","29:17":"وتقطع الكبش إلى قطعه, وتغسل جوفه وأكارعه وتجعلها على قطعه وعلى رأسه,","29:18":"وتوقد كل الكبش على المذبح. هو محرقة للرب. رائحة سرور, وقود هو للرب.","29:19":"«وتأخذ الكبش الثاني, فيضع هارون وبنوه أيديهم على رأس الكبش.","29:20":"فتذبح الكبش وتأخذ من دمه وتجعل على شحمة أذن هارون, وعلى شحم آذان بنيه اليمنى, وعلى أباهم أيديهم اليمنى, وعلى أباهم أرجلهم اليمنى. وترش الدم على المذبح من كل ناحية.","29:21":"وتأخذ من الدم الذي على المذبح ومن دهن المسحة, وتنضح على هارون وثيابه, وعلى بنيه وثياب بنيه معه, فيتقدس هو وثيابه وبنوه وثياب بنيه معه.","29:22":"ثم تأخذ من الكبش: الشحم والإلية والشحم الذي يغشي الجوف, وزيادة الكبد والكليتين, والشحم الذي عليهما, والساق اليمنى. فإنه كبش ملء.","29:23":"ورغيفا واحدا من الخبز, وقرصا واحدا من الخبز بزيت, ورقاقة واحدة من سلة الفطير التي أمام الرب.","29:24":"وتضع الجميع في يدي هارون وفي أيدي بنيه, وترددها ترديدا أمام الرب.","29:25":"ثم تأخذها من أيديهم وتوقدها على المذبح فوق المحرقة رائحة سرور أمام الرب. وقود هو للرب.","29:26":"«ثم تأخذ القص من كبش الملء الذي لهارون, وتردده ترديدا أمام الرب, فيكون لك نصيبا.","29:27":"وتقدس قص الترديد وساق الرفيعة الذي ردد والذي رفع من كبش الملء مما لهارون ولبنيه,","29:28":"فيكونان لهارون وبنيه فريضة أبدية من بني إسرائيل لأنهما رفيعة. ويكونان رفيعة من بني إسرائيل من ذبائح سلامتهم, رفيعتهم للرب.","29:29":"«والثياب المقدسة التي لهارون تكون لبنيه بعده, ليمسحوا فيها, ولتملأ فيها أيديهم.","29:30":"سبعة أيام يلبسها الكاهن الذي هو عوض عنه من بنيه, الذي يدخل خيمة الاجتماع ليخدم في القدس.","29:31":"«وأما كبش الملء فتأخذه وتطبخ لحمه في مكان مقدس.","29:32":"فيأكل هارون وبنوه لحم الكبش والخبز الذي في السلة عند باب خيمة الاجتماع.","29:33":"يأكلها الذين كفر بها عنهم لملء أيديهم لتقديسهم. وأما الأجنبي فلا يأكل لأنها مقدسة.","29:34":"وإن بقي شيء من لحم الملء أو من الخبز إلى الصباح, تحرق الباقي بالنار. لا يؤكل لأنه مقدس.","29:35":"وتصنع لهارون وبنيه هكذا بحسب كل ما أمرتك. سبعة أيام تملأ أيديهم.","29:36":"وتقدم ثور خطية كل يوم لأجل الكفارة. وتطهر المذبح بتكفيرك عليه, وتمسحه لتقديسه.","29:37":"سبعة أيام تكفر على المذبح وتقدسه, فيكون المذبح قدس أقداس. كل ما مس المذبح يكون مقدسا.","29:38":"«وهذا ما تقدمه على المذبح: خروفان حوليان كل يوم دائما.","29:39":"الخروف الواحد تقدمه صباحا, والخروف الثاني تقدمه في العشية.","29:40":"وعشر من دقيق ملتوت بربع الهين من زيت الرض, وسكيب ربع الهين من الخمر للخروف الواحد.","29:41":"والخروف الثاني تقدمه في العشية. مثل تقدمة الصباح وسكيبه تصنع له. رائحة سرور, وقود للرب.","29:42":"محرقة دائمة في أجيالكم عند باب خيمة الاجتماع أمام الرب, حيث أجتمع بكم لأكلمك هناك.","29:43":"وأجتمع هناك ببني إسرائيل فيقدس بمجدي.","29:44":"وأقدس خيمة الاجتماع والمذبح, وهارون وبنوه أقدسهم لكي يكهنوا لي.","29:45":"وأسكن في وسط بني إسرائيل وأكون لهم إلها,","29:46":"فيعلمون أني أنا الرب إلههم الذي أخرجهم من أرض مصر لأسكن في وسطهم. أنا الرب إلههم.","30:1":"«وتصنع مذبحا لإيقاد البخور. من خشب السنط تصنعه.","30:2":"طوله ذراع وعرضه ذراع. مربعا يكون. وارتفاعه ذراعان. منه تكون قرونه.","30:3":"وتغشيه بذهب نقي: سطحه وحيطانه حواليه وقرونه. وتصنع له إكليلا من ذهب حواليه.","30:4":"وتصنع له حلقتين من ذهب تحت إكليله على جانبيه. على الجانبين تصنعهما, لتكونا بيتين لعصوين لحمله بهما.","30:5":"وتصنع العصوين من خشب السنط وتغشيهما بذهب.","30:6":"وتجعله قدام الحجاب الذي أمام تابوت الشهادة. قدام الغطاء الذي على الشهادة حيث أجتمع بك.","30:7":"فيوقد عليه هارون بخورا عطرا كل صباح, حين يصلح السرج يوقده.","30:8":"وحين يصعد هارون السرج في العشية يوقده. بخورا دائما أمام الرب في أجيالكم.","30:9":"لا تصعدوا عليه بخورا غريبا ولا محرقة أو تقدمة, ولا تسكبوا عليه سكيبا.","30:10":"ويصنع هارون كفارة على قرونه مرة في السنة. من دم ذبيحة الخطية التي للكفارة مرة في السنة يصنع كفارة عليه في أجيالكم. قدس أقداس هو للرب».","30:11":"وكلم الرب موسى قائلا:","30:12":"«إذا أخذت كمية بني إسرائيل بحسب المعدودين منهم, يعطون كل واحد فدية نفسه للرب عندما تعدهم, لئلا يصير فيهم وبأ عندما تعدهم.","30:13":"هذا ما يعطيه كل من اجتاز إلى المعدودين: نصف الشاقل بشاقل القدس. الشاقل هو عشرون جيرة. نصف الشاقل تقدمة للرب.","30:14":"كل من اجتاز إلى المعدودين من ابن عشرين سنة فصاعدا يعطي تقدمة للرب.","30:15":"الغني لا يكثر والفقير لا يقلل عن نصف الشاقل حين تعطون تقدمة الرب للتكفير عن نفوسكم.","30:16":"وتأخذ فضة الكفارة من بني إسرائيل, وتجعلها لخدمة خيمة الاجتماع. فتكون لبني إسرائيل تذكارا أمام الرب للتكفير عن نفوسكم».","30:17":"وكلم الرب موسى قائلا:","30:18":"«وتصنع مرحضة من نحاس, وقاعدتها من نحاس, للاغتسال. وتجعلها بين خيمة الاجتماع والمذبح, وتجعل فيها ماء.","30:19":"فيغسل هارون وبنوه أيديهم وأرجلهم منها.","30:20":"عند دخولهم إلى خيمة الاجتماع يغسلون بماء لئلا يموتوا, أو عند اقترابهم إلى المذبح للخدمة ليوقدوا وقودا للرب.","30:21":"يغسلون أيديهم وأرجلهم لئلا يموتوا. ويكون لهم فريضة أبدية له ولنسله في أجيالهم».","30:22":"وكلم الرب موسى قائلا:","30:23":"«وأنت تأخذ لك أفخر الأطياب: مرا قاطرا خمس مئة شاقل, وقرفة عطرة نصف ذلك: مئتين وخمسين, وقصب الذريرة مئتين وخمسين,","30:24":"وسليخة خمس مئة بشاقل القدس, ومن زيت الزيتون هينا.","30:25":"وتصنعه دهنا مقدسا للمسحة. عطر عطارة صنعة العطار. دهنا مقدسا للمسحة يكون.","30:26":"وتمسح به خيمة الاجتماع, وتابوت الشهادة,","30:27":"والمائدة وكل آنيتها, والمنارة وآنيتها, ومذبح البخور,","30:28":"ومذبح المحرقة وكل آنيته, والمرحضة وقاعدتها.","30:29":"وتقدسها فتكون قدس أقداس. كل ما مسها يكون مقدسا.","30:30":"وتمسح هارون وبنيه وتقدسهم ليكهنوا لي.","30:31":"وتكلم بني إسرائيل قائلا: يكون هذا لي دهنا مقدسا للمسحة في أجيالكم.","30:32":"على جسد إنسان لا يسكب, وعلى مقاديره لا تصنعوا مثله. مقدس هو, ويكون مقدسا عندكم.","30:33":"كل من ركب مثله ومن جعل منه على أجنبي يقطع من شعبه».","30:34":"وقال الرب لموسى: «خذ لك أعطارا: ميعة وأظفارا وقنة عطرة ولبانا نقيا. تكون أجزاء متساوية,","30:35":"فتصنعها بخورا عطرا صنعة العطار, مملحا نقيا مقدسا.","30:36":"وتسحق منه ناعما, وتجعل منه قدام الشهادة في خيمة الاجتماع حيث أجتمع بك. قدس أقداس يكون عندكم.","30:37":"والبخور الذي تصنعه على مقاديره لا تصنعوا لأنفسكم. يكون عندك مقدسا للرب.","30:38":"كل من صنع مثله ليشمه يقطع من شعبه».","31:1":"وكلم الرب موسى قائلا:","31:2":"«انظر. قد دعوت بصلئيل بن أوري بن حور من سبط يهوذا باسمه,","31:3":"وملأته من روح الله بالحكمة والفهم والمعرفة وكل صنعة,","31:4":"لاختراع مخترعات ليعمل في الذهب والفضة والنحاس,","31:5":"ونقش حجارة للترصيع, ونجارة الخشب, ليعمل في كل صنعة.","31:6":"وها أنا قد جعلت معه أهوليآب بن أخيساماك من سبط دان. وفي قلب كل حكيم القلب جعلت حكمة, ليصنعوا كل ما أمرتك:","31:7":"خيمة الاجتماع, وتابوت الشهادة, والغطاء الذي عليه, وكل آنية الخيمة,","31:8":"والمائدة وآنيتها, والمنارة الطاهرة وكل آنيتها, ومذبح البخور,","31:9":"ومذبح المحرقة وكل آنيته, والمرحضة وقاعدتها,","31:10":"والثياب المنسوجة, والثياب المقدسة لهارون الكاهن وثياب بنيه للكهانة,","31:11":"ودهن المسحة والبخور العطر للقدس. حسب كل ما أمرتك به يصنعون».","31:12":"وكلم الرب موسى قائلا:","31:13":"«وأنت تكلم بني إسرائيل قائلا: سبوتي تحفظونها, لأنه علامة بيني وبينكم في أجيالكم لتعلموا أني أنا الرب الذي يقدسكم,","31:14":"فتحفظون السبت لأنه مقدس لكم. من دنسه يقتل قتلا. إن كل من صنع فيه عملا تقطع تلك النفس من بين شعبها.","31:15":"ستة أيام يصنع عمل, وأما اليوم السابع ففيه سبت عطلة مقدس للرب. كل من صنع عملا في يوم السبت يقتل قتلا.","31:16":"فيحفظ بنو إسرائيل السبت ليصنعوا السبت في أجيالهم عهدا أبديا.","31:17":"هو بيني وبين بني إسرائيل علامة إلى الأبد. لأنه في ستة أيام صنع الرب السماء والأرض, وفي اليوم السابع استراح وتنفس».","31:18":"ثم أعطى موسى عند فراغه من الكلام معه في جبل سيناء لوحي الشهادة: لوحي حجر مكتوبين بإصبع الله.","32:1":"ولما رأى الشعب أن موسى أبطأ في النزول من الجبل, اجتمع الشعب على هارون وقالوا له: «قم اصنع لنا آلهة تسير أمامنا, لأن هذا موسى الرجل الذي أصعدنا من أرض مصر, لا نعلم ماذا أصابه».","32:2":"فقال لهم هارون: «انزعوا أقراط الذهب التي في آذان نسائكم وبنيكم وبناتكم واتوني بها».","32:3":"فنزع كل الشعب أقراط الذهب التي في آذانهم وأتوا بها إلى هارون.","32:4":"فأخذ ذلك من أيديهم وصوره بالإزميل, وصنعه عجلا مسبوكا. فقالوا: «هذه آلهتك يا إسرائيل التي أصعدتك من أرض مصر».","32:5":"فلما نظر هارون بنى مذبحا أمامه, ونادى هارون وقال: «غدا عيد للرب».","32:6":"فبكروا في الغد وأصعدوا محرقات وقدموا ذبائح سلامة. وجلس الشعب للأكل والشرب ثم قاموا للعب.","32:7":"فقال الرب لموسى: «اذهب انزل. لأنه قد فسد شعبك الذي أصعدته من أرض مصر.","32:8":"زاغوا سريعا عن الطريق الذي أوصيتهم به. صنعوا لهم عجلا مسبوكا, وسجدوا له وذبحوا له وقالوا: هذه آلهتك يا إسرائيل التي أصعدتك من أرض مصر».","32:9":"وقال الرب لموسى: «رأيت هذا الشعب وإذا هو شعب صلب الرقبة.","32:10":"فالآن اتركني ليحمى غضبي عليهم وأفنيهم, فأصيرك شعبا عظيما».","32:11":"فتضرع موسى أمام الرب إلهه, وقال: «لماذا يا رب يحمى غضبك على شعبك الذي أخرجته من أرض مصر بقوة عظيمة ويد شديدة؟","32:12":"لماذا يتكلم المصريون قائلين: أخرجهم بخبث ليقتلهم في الجبال, ويفنيهم عن وجه الأرض؟ ارجع عن حمو غضبك, واندم على الشر بشعبك.","32:13":"اذكر إبراهيم وإسحاق وإسرائيل عبيدك الذين حلفت لهم بنفسك وقلت لهم: أكثر نسلكم كنجوم السماء, وأعطي نسلكم كل هذه الأرض التي تكلمت عنها فيملكونها إلى الأبد».","32:14":"فندم الرب على الشر الذي قال إنه يفعله بشعبه.","32:15":"فانصرف موسى ونزل من الجبل ولوحا الشهادة في يده: لوحان مكتوبان على جانبيهما. من هنا ومن هنا كانا مكتوبين.","32:16":"واللوحان هما صنعة الله, والكتابة كتابة الله منقوشة على اللوحين.","32:17":"وسمع يشوع صوت الشعب في هتافه فقال لموسى: «صوت قتال في المحلة».","32:18":"فقال: «ليس صوت صياح النصرة ولا صوت صياح الكسرة, بل صوت غناء أنا سامع».","32:19":"وكان عندما اقترب إلى المحلة أنه أبصر العجل والرقص, فحمي غضب موسى, وطرح اللوحين من يديه وكسرهما في أسفل الجبل.","32:20":"ثم أخذ العجل الذي صنعوا وأحرقه بالنار, وطحنه حتى صار ناعما, وذراه على وجه الماء, وسقى بني إسرائيل.","32:21":"وقال موسى لهارون: «ماذا صنع بك هذا الشعب حتى جلبت عليه خطية عظيمة؟»","32:22":"فقال هارون: «لا يحم غضب سيدي. أنت تعرف الشعب أنه في شر.","32:23":"فقالوا لي: اصنع لنا آلهة تسير أمامنا, لأن هذا موسى الرجل الذي أصعدنا من أرض مصر, لا نعلم ماذا أصابه.","32:24":"فقلت لهم: من له ذهب فلينزعه ويعطني. فطرحته في النار فخرج هذا العجل».","32:25":"ولما رأى موسى الشعب أنه معرى لأن هارون كان قد عراه للهزء بين مقاوميه,","32:26":"وقف موسى في باب المحلة, وقال: «من للرب فإلي». فاجتمع إليه جميع بني لاوي.","32:27":"فقال لهم: «هكذا قال الرب إله إسرائيل: ضعوا كل واحد سيفه على فخذه ومروا وارجعوا من باب إلى باب في المحلة, واقتلوا كل واحد أخاه وكل واحد صاحبه وكل واحد قريبه».","32:28":"ففعل بنو لاوي بحسب قول موسى. ووقع من الشعب في ذلك اليوم نحو ثلاثة آلاف رجل.","32:29":"وقال موسى: «املأوا أيديكم اليوم للرب, حتى كل واحد بابنه وبأخيه, فيعطيكم اليوم بركة».","32:30":"وكان في الغد أن موسى قال للشعب: «أنتم قد أخطأتم خطية عظيمة, فأصعد الآن إلى الرب لعلي أكفر خطيتكم».","32:31":"فرجع موسى إلى الرب, وقال: «آه, قد أخطأ هذا الشعب خطية عظيمة وصنعوا لأنفسهم آلهة من ذهب.","32:32":"والآن إن غفرت خطيتهم, وإلا فامحني من كتابك الذي كتبت».","32:33":"فقال الرب لموسى: «من أخطأ إلي أمحوه من كتابي.","32:34":"والآن اذهب اهد الشعب إلى حيث كلمتك. هوذا ملاكي يسير أمامك. ولكن في يوم افتقادي أفتقد فيهم خطيتهم».","32:35":"فضرب الرب الشعب, لأنهم صنعوا العجل الذي صنعه هارون.","33:1":"وقال الرب لموسى: «اذهب اصعد من هنا أنت والشعب الذي أصعدته من أرض مصر إلى الأرض التي حلفت لإبراهيم وإسحاق ويعقوب قائلا: لنسلك أعطيها.","33:2":"وأنا أرسل أمامك ملاكا, وأطرد الكنعانيين والأموريين والحثيين والفرزيين والحويين واليبوسيين.","33:3":"إلى أرض تفيض لبنا وعسلا. فإني لا أصعد في وسطك لأنك شعب صلب الرقبة, لئلا أفنيك في الطريق».","33:4":"فلما سمع الشعب هذا الكلام السوء ناحوا ولم يضع أحد زينته عليه.","33:5":"وكان الرب قد قال لموسى: «قل لبني إسرائيل: أنتم شعب صلب الرقبة. إن صعدت لحظة واحدة في وسطكم أفنيتكم. ولكن الآن اخلع زينتك عنك فأعلم ماذا أصنع بك».","33:6":"فنزع بنو إسرائيل زينتهم من جبل حوريب.","33:7":"وأخذ موسى الخيمة ونصبها له خارج المحلة, بعيدا عن المحلة, ودعاها «خيمة الاجتماع». فكان كل من يطلب الرب يخرج إلى خيمة الاجتماع التي خارج المحلة.","33:8":"وكان جميع الشعب إذا خرج موسى إلى الخيمة يقومون ويقفون كل واحد في باب خيمته وينظرون وراء موسى حتى يدخل الخيمة.","33:9":"وكان عمود السحاب إذا دخل موسى الخيمة, ينزل ويقف عند باب الخيمة. ويتكلم الرب مع موسى.","33:10":"فيرى جميع الشعب عمود السحاب, واقفا عند باب الخيمة, ويقوم كل الشعب ويسجدون كل واحد في باب خيمته.","33:11":"ويكلم الرب موسى وجها لوجه, كما يكلم الرجل صاحبه. وإذا رجع موسى إلى المحلة كان خادمه يشوع بن نون الغلام, لا يبرح من داخل الخيمة.","33:12":"وقال موسى للرب: «انظر. أنت قائل لي: أصعد هذا الشعب, وأنت لم تعرفني من ترسل معي. وأنت قد قلت: عرفتك باسمك, ووجدت أيضا نعمة في عيني.","33:13":"فالآن إن كنت قد وجدت نعمة في عينيك فعلمني طريقك حتى أعرفك لكي أجد نعمة في عينيك. وانظر أن هذه الأمة شعبك».","33:14":"فقال: «وجهي يسير فأريحك».","33:15":"فقال له: «إن لم يسر وجهك فلا تصعدنا من ههنا,","33:16":"فإنه بماذا يعلم أني وجدت نعمة في عينيك أنا وشعبك؟ أليس بمسيرك معنا؟ فنمتاز أنا وشعبك عن جميع الشعوب الذين على وجه الأرض».","33:17":"فقال الرب لموسى: «هذا الأمر أيضا الذي تكلمت عنه أفعله, لأنك وجدت نعمة في عيني, وعرفتك باسمك».","33:18":"فقال: «أرني مجدك».","33:19":"فقال: «أجيز كل جودتي قدامك. وأنادي باسم الرب قدامك. وأتراءف على من أتراءف, وأرحم من أرحم».","33:20":"وقال: «لا تقدر أن ترى وجهي, لأن الإنسان لا يراني ويعيش».","33:21":"وقال الرب: «هوذا عندي مكان, فتقف على الصخرة.","33:22":"ويكون متى اجتاز مجدي, أني أضعك في نقرة من الصخرة, وأسترك بيدي حتى أجتاز.","33:23":"ثم أرفع يدي فتنظر ورائي, وأما وجهي فلا يرى».","34:1":"ثم قال الرب لموسى: «انحت لك لوحين من حجر مثل الأولين, فأكتب أنا على اللوحين الكلمات التي كانت على اللوحين الأولين اللذين كسرتهما.","34:2":"وكن مستعدا للصباح. واصعد في الصباح إلى جبل سيناء, وقف عندي هناك على رأس الجبل.","34:3":"ولا يصعد أحد معك, وأيضا لا ير أحد في كل الجبل. الغنم أيضا والبقر لا ترع إلى جهة ذلك الجبل».","34:4":"فنحت لوحين من حجر كالأولين. وبكر موسى في الصباح وصعد إلى جبل سيناء كما أمره الرب, وأخذ في يده لوحي الحجر.","34:5":"فنزل الرب في السحاب, فوقف عنده هناك ونادى باسم الرب.","34:6":"فاجتاز الرب قدامه, ونادى الرب: «الرب إله رحيم ورؤوف, بطيء الغضب وكثير الإحسان والوفاء.","34:7":"حافظ الإحسان إلى ألوف. غافر الإثم والمعصية والخطية. ولكنه لن يبرئ إبراء. مفتقد إثم الآباء في الأبناء, وفي أبناء الأبناء, في الجيل الثالث والرابع».","34:8":"فأسرع موسى وخر إلى الأرض وسجد.","34:9":"وقال: «إن وجدت نعمة في عينيك أيها السيد فليسر السيد في وسطنا, فإنه شعب صلب الرقبة. واغفر إثمنا وخطيتنا واتخذنا ملكا».","34:10":"فقال: «ها أنا قاطع عهدا. قدام جميع شعبك أفعل عجائب لم تخلق في كل الأرض وفي جميع الأمم, فيرى جميع الشعب الذي أنت في وسطه فعل الرب. إن الذي أنا فاعله معك رهيب.","34:11":"«احفظ ما أنا موصيك اليوم. ها أنا طارد من قدامك الأموريين والكنعانيين والحثيين والفرزيين والحويين واليبوسيين.","34:12":"احترز من أن تقطع عهدا مع سكان الأرض التي أنت آت إليها لئلا يصيروا فخا في وسطك,","34:13":"بل تهدمون مذابحهم, وتكسرون أنصابهم, وتقطعون سواريهم.","34:14":"فإنك لا تسجد لإله آخر, لأن الرب اسمه غيور. إله غيور هو.","34:15":"احترز من أن تقطع عهدا مع سكان الأرض, فيزنون وراء آلهتهم ويذبحون لآلهتهم, فتدعى وتأكل من ذبيحتهم,","34:16":"وتأخذ من بناتهم لبنيك, فتزني بناتهم وراء آلهتهن, ويجعلن بنيك يزنون وراء آلهتهن.","34:17":"«لا تصنع لنفسك آلهة مسبوكة.","34:18":"تحفظ عيد الفطير. سبعة أيام تأكل فطيرا كما أمرتك في وقت شهر أبيب, لأنك في شهر أبيب خرجت من مصر.","34:19":"لي كل فاتح رحم, وكل ما يولد ذكرا من مواشيك بكرا من ثور وشاة.","34:20":"وأما بكر الحمار فتفديه بشاة, وإن لم تفده تكسر عنقه. كل بكر من بنيك تفديه, ولا يظهروا أمامي فارغين.","34:21":"ستة أيام تعمل, وأما اليوم السابع فتستريح فيه. في الفلاحة وفي الحصاد تستريح.","34:22":"وتصنع لنفسك عيد الأسابيع أبكار حصاد الحنطة. وعيد الجمع في آخر السنة.","34:23":"ثلاث مرات في السنة يظهر جميع ذكورك أمام السيد الرب إله إسرائيل.","34:24":"فإني أطرد الأمم من قدامك وأوسع تخومك, ولا يشتهي أحد أرضك حين تصعد لتظهر أمام الرب إلهك ثلاث مرات في السنة.","34:25":"لا تذبح على خمير دم ذبيحتي, ولا تبت إلى الغد ذبيحة عيد الفصح.","34:26":"أول أبكار أرضك تحضره إلى بيت الرب إلهك. لا تطبخ جديا بلبن أمه».","34:27":"وقال الرب لموسى: «اكتب لنفسك هذه الكلمات, لأنني بحسب هذه الكلمات قطعت عهدا معك ومع إسرائيل».","34:28":"وكان هناك عند الرب أربعين نهارا وأربعين ليلة, لم يأكل خبزا ولم يشرب ماء. فكتب على اللوحين كلمات العهد, الكلمات العشر.","34:29":"وكان لما نزل موسى من جبل سيناء ولوحا الشهادة في يد موسى, عند نزوله من الجبل, أن موسى لم يعلم أن جلد وجهه صار يلمع في كلامه معه.","34:30":"فنظر هارون وجميع بني إسرائيل موسى وإذا جلد وجهه يلمع, فخافوا أن يقتربوا إليه.","34:31":"فدعاهم موسى. فرجع إليه هارون وجميع الرؤساء في الجماعة, فكلمهم موسى.","34:32":"وبعد ذلك اقترب جميع بني إسرائيل, فأوصاهم بكل ما تكلم به الرب معه في جبل سيناء.","34:33":"ولما فرغ موسى من الكلام معهم, جعل على وجهه برقعا.","34:34":"وكان موسى عند دخوله أمام الرب ليتكلم معه ينزع البرقع حتى يخرج, ثم يخرج ويكلم بني إسرائيل بما يوصى.","34:35":"فإذا رأى بنو إسرائيل وجه موسى أن جلده يلمع كان موسى يرد البرقع على وجهه حتى يدخل ليتكلم معه.","35:1":"وجمع موسى كل جماعة بني إسرائيل وقال لهم: «هذه هي الكلمات التي أمر الرب أن تصنع:","35:2":"ستة أيام يعمل عمل, وأما اليوم السابع ففيه يكون لكم سبت عطلة مقدس للرب. كل من يعمل فيه عملا يقتل.","35:3":"لا تشعلوا نارا في جميع مساكنكم يوم السبت».","35:4":"وكلم موسى كل جماعة بني إسرائيل قائلا: «هذا هو الشيء الذي أمر به الرب قائلا:","35:5":"خذوا من عندكم تقدمة للرب. كل من قلبه سموح فليأت بتقدمة الرب: ذهبا وفضة ونحاسا,","35:6":"وأسمانجونيا وأرجوانا وقرمزا وبوصا وشعر معزى,","35:7":"وجلود كباش محمرة وجلود تخس وخشب سنط,","35:8":"وزيتا للضوء وأطيابا لدهن المسحة وللبخور العطر,","35:9":"وحجارة جزع وحجارة ترصيع للرداء والصدرة.","35:10":"وكل حكيم القلب بينكم فليأت ويصنع كل ما أمر به الرب:","35:11":"المسكن وخيمته وغطاءه وأشظته وألواحه وعوارضه وأعمدته وقواعده,","35:12":"والتابوت وعصويه, والغطاء وحجاب السجف,","35:13":"والمائدة وعصويها وكل آنيتها, وخبز الوجوه,","35:14":"ومنارة الضوء وآنيتها وسرجها وزيت الضوء,","35:15":"ومذبح البخور وعصويه, ودهن المسحة والبخور العطر, وسجف الباب لمدخل المسكن,","35:16":"ومذبح المحرقة وشباكة النحاس التي له وعصويه وكل آنيته, والمرحضة وقاعدتها,","35:17":"وأستار الدار وأعمدتها وقواعدها, وسجف باب الدار,","35:18":"وأوتاد المسكن, وأوتاد الدار وأطنابها,","35:19":"والثياب المنسوجة للخدمة في المقدس, والثياب المقدسة لهارون الكاهن, وثياب بنيه للكهانة».","35:20":"فخرج كل جماعة بني إسرائيل من قدام موسى,","35:21":"ثم جاء كل من أنهضه قلبه, وكل من سمحته روحه. جاءوا بتقدمة الرب لعمل خيمة الاجتماع ولكل خدمتها وللثياب المقدسة.","35:22":"وجاء الرجال مع النساء, كل سموح القلب, جاء بخزائم وأقراط وخواتم وقلائد, كل متاع من الذهب. وكل من قدم تقدمة ذهب للرب.","35:23":"وكل من وجد عنده أسمانجوني وأرجوان وقرمز وبوص وشعر معزى وجلود كباش محمرة وجلود تخس, جاء بها.","35:24":"كل من قدم تقدمة فضة ونحاس جاء بتقدمة الرب. وكل من وجد عنده خشب سنط لصنعة ما من العمل جاء به.","35:25":"وكل النساء الحكيمات القلب غزلن بأيديهن وجئن من الغزل بالأسمانجوني والأرجوان والقرمز والبوص.","35:26":"وكل النساء اللواتي أنهضتهن قلوبهن بالحكمة غزلن شعر المعزى.","35:27":"والرؤساء جاءوا بحجارة الجزع وحجارة الترصيع للرداء والصدرة,","35:28":"وبالطيب والزيت للضوء ولدهن المسحة وللبخور العطر.","35:29":"بنو إسرائيل, جميع الرجال والنساء الذين سمحتهم قلوبهم أن يأتوا بشيء لكل العمل الذي أمر الرب أن يصنع على يد موسى, جاءوا به تبرعا إلى الرب.","35:30":"وقال موسى لبني إسرائيل: «انظروا. قد دعا الرب بصلئيل بن أوري بن حور من سبط يهوذا باسمه,","35:31":"وملأه من روح الله بالحكمة والفهم والمعرفة وكل صنعة,","35:32":"ولاختراع مخترعات, ليعمل في الذهب والفضة والنحاس,","35:33":"ونقش حجارة للترصيع, ونجارة الخشب, ليعمل في كل صنعة من المخترعات.","35:34":"وجعل في قلبه أن يعلم هو وأهوليآب بن أخيساماك من سبط دان.","35:35":"قد ملأهما حكمة قلب ليصنعا كل عمل النقاش والحائك الحاذق والطراز في الأسمانجوني والأرجوان والقرمز والبوص وكل عمل النساج. صانعي كل صنعة ومخترعي المخترعات.","36:1":"«فيعمل بصلئيل وأهوليآب وكل إنسان حكيم القلب, قد جعل فيه الرب حكمة وفهما ليعرف أن يصنع صنعة ما من عمل المقدس, بحسب كل ما أمر الرب».","36:2":"فدعا موسى بصلئيل وأهوليآب وكل رجل حكيم القلب, قد جعل الرب حكمة في قلبه, كل من أنهضه قلبه أن يتقدم إلى العمل ليصنعه.","36:3":"فأخذوا من قدام موسى كل التقدمة التي جاء بها بنو إسرائيل لصنعة عمل المقدس لكي يصنعوه. وهم جاءوا إليه أيضا بشيء تبرعا كل صباح.","36:4":"فجاء كل الحكماء الصانعين كل عمل المقدس, كل واحد من عمله الذي هم يصنعونه.","36:5":"وكلموا موسى قائلين: «يجيء الشعب بكثير فوق حاجة العمل للصنعة التي أمر الرب بصنعها».","36:6":"فأمر موسى أن ينفذوا صوتا في المحلة قائلين: «لا يصنع رجل أو امرأة عملا أيضا لتقدمة المقدس». فامتنع الشعب عن الجلب.","36:7":"والمواد كانت كفايتهم لكل العمل ليصنعوه وأكثر.","36:8":"فصنعوا كل حكيم قلب من صانعي العمل المسكن عشر شقق من بوص مبروم وأسمانجوني وأرجوان وقرمز بكروبيم, صنعة حائك حاذق صنعها.","36:9":"طول الشقة الواحدة ثمان وعشرون ذراعا, وعرض الشقة الواحدة أربع أذرع. قياسا واحدا لجميع الشقق.","36:10":"ووصل خمسا من الشقق بعضها ببعض. ووصل خمسا من الشقق بعضها ببعض.","36:11":"وصنع عرى من أسمانجوني على حاشية الشقة الواحدة في الطرف من الموصل الواحد. كذلك صنع في حاشية الشقة الطرفية من الموصل الثاني.","36:12":"خمسين عروة صنع في الشقة الواحدة, وخمسين عروة صنع في طرف الشقة الذي في الموصل الثاني. مقابلة كانت العرى بعضها لبعض.","36:13":"وصنع خمسين شظاظا من ذهب, ووصل الشقتين بعضهما ببعض بالأشظة, فصار المسكن واحدا.","36:14":"وصنع شققا من شعر معزى خيمة فوق المسكن. إحدى عشرة شقة صنعها.","36:15":"طول الشقة الواحدة ثلاثون ذراعا, وعرض الشقة الواحدة أربع أذرع. قياسا واحدا للإحدى عشرة شقة.","36:16":"ووصل خمسا من الشقق وحدها, وستا من الشقق وحدها.","36:17":"وصنع خمسين عروة على حاشية الشقة الطرفية من الموصل الواحد. وصنع خمسين عروة على حاشية الشقة الموصلة الثانية.","36:18":"وصنع خمسين شظاظا من نحاس ليصل الخيمة لتصير واحدة.","36:19":"وصنع غطاء للخيمة من جلود كباش محمرة, وغطاء من جلود تخس من فوق.","36:20":"وصنع الألواح للمسكن من خشب السنط قائمة.","36:21":"طول اللوح عشر أذرع, وعرض اللوح الواحد ذراع ونصف.","36:22":"وللوح الواحد رجلان, مقرونة إحداهما بالأخرى. هكذا صنع لجميع ألواح المسكن.","36:23":"وصنع الألواح للمسكن عشرين لوحا إلى جهة الجنوب نحو التيمن.","36:24":"وصنع أربعين قاعدة من فضة تحت العشرين لوحا, تحت اللوح الواحد قاعدتان لرجليه, وتحت اللوح الواحد قاعدتان لرجليه.","36:25":"ولجانب المسكن الثاني إلى جهة الشمال صنع عشرين لوحا,","36:26":"وأربعين قاعدة لها من فضة. تحت اللوح الواحد قاعدتان, وتحت اللوح الواحد قاعدتان.","36:27":"ولمؤخر المسكن نحو الغرب صنع ستة ألواح.","36:28":"وصنع لوحين لزاويتي المسكن في المؤخر.","36:29":"وكانا مزدوجين من أسفل, وعلى سواء كانا مزدوجين إلى رأسه إلى الحلقة الواحدة. هكذا صنع لكلتيهما, لكلتا الزاويتين.","36:30":"فكانت ثمانية ألواح وقواعدها من فضة ست عشرة قاعدة. قاعدتين قاعدتين تحت اللوح الواحد.","36:31":"وصنع عوارض من خشب السنط, خمسا لألواح جانب المسكن الواحد,","36:32":"وخمس عوارض لألواح جانب المسكن الثاني, وخمس عوارض لألواح المسكن في المؤخر نحو الغرب.","36:33":"وصنع العارضة الوسطى لتنفذ في وسط الألواح من الطرف إلى الطرف.","36:34":"وغشى الألواح بذهب. وصنع حلقاتها من ذهب بيوتا للعوارض, وغشى العوارض بذهب.","36:35":"وصنع الحجاب من أسمانجوني وأرجوان وقرمز وبوص مبروم. صنعة حائك حاذق صنعه بكروبيم.","36:36":"وصنع له أربعة أعمدة من سنط, وغشاها بذهب. رززها من ذهب. وسبك لها أربع قواعد من فضة.","36:37":"وصنع سجفا لمدخل الخيمة من أسمانجوني وأرجوان وقرمز وبوص مبروم صنعة الطراز.","36:38":"وأعمدته خمسة ورززها. وغشى رؤوسها وقضبانها بذهب, وقواعدها خمسا من نحاس.","37:1":"وصنع بصلئيل التابوت من خشب السنط, طوله ذراعان ونصف, وعرضه ذراع ونصف, وارتفاعه ذراع ونصف.","37:2":"وغشاه بذهب نقي من داخل ومن خارج. وصنع له إكليلا من ذهب حواليه.","37:3":"وسبك له أربع حلقات من ذهب على أربع قوائمه. على جانبه الواحد حلقتان, وعلى جانبه الثاني حلقتان.","37:4":"وصنع عصوين من خشب السنط وغشاهما بذهب.","37:5":"وأدخل العصوين في الحلقات على جانبي التابوت, لحمل التابوت.","37:6":"وصنع غطاء من ذهب نقي, طوله ذراعان ونصف, وعرضه ذراع ونصف.","37:7":"وصنع كروبين من ذهب صنعة الخراطة, صنعهما على طرفي الغطاء.","37:8":"كروبا واحدا على الطرف من هنا, وكروبا واحدا على الطرف من هناك. من الغطاء صنع الكروبين على طرفيه.","37:9":"وكان الكروبان باسطين أجنحتهما إلى فوق, مظللين بأجنحتهما فوق الغطاء, ووجهاهما كل الواحد إلى الآخر. نحو الغطاء كان وجها الكروبين.","37:10":"وصنع المائدة من خشب السنط, طولها ذراعان, وعرضها ذراع, وارتفاعها ذراع ونصف.","37:11":"وغشاها بذهب نقي, وصنع لها إكليلا من ذهب حواليها.","37:12":"وصنع لها حاجبا على شبر حواليها, وصنع لحاجبها إكليلا من ذهب حواليها.","37:13":"وسبك لها أربع حلقات من ذهب, وجعل الحلقات على الزوايا الأربع التي لقوائمها الأربع.","37:14":"عند الحاجب كانت الحلقات بيوتا للعصوين لحمل المائدة.","37:15":"وصنع العصوين من خشب السنط, وغشاهما بذهب لحمل المائدة.","37:16":"وصنع الأواني التي على المائدة, صحافها وصحونها وجاماتها وكأساتها التي يسكب بها من ذهب نقي.","37:17":"وصنع المنارة من ذهب نقي. صنعة الخراطة صنع المنارة, قاعدتها وساقها. كانت كأساتها وعجرها وأزهارها منها.","37:18":"وست شعب خارجة من جانبيها. من جانبها الواحد ثلاث شعب منارة, ومن جانبها الثاني ثلاث شعب منارة.","37:19":"في الشعبة الواحدة ثلاث كأسات لوزية بعجرة وزهر, وفي الشعبة الثانية ثلاث كأسات لوزية بعجرة وزهر, وهكذا إلى الست الشعب الخارجة من المنارة.","37:20":"وفي المنارة أربع كأسات لوزية بعجرها وأزهارها.","37:21":"وتحت الشعبتين منها عجرة, وتحت الشعبتين منها عجرة, وتحت الشعبتين منها عجرة. إلى الست الشعب الخارجة منها.","37:22":"كانت عجرها وشعبها منها, جميعها خراطة واحدة من ذهب نقي.","37:23":"وصنع سرجها سبعة, وملاقطها ومنافضها من ذهب نقي.","37:24":"من وزنة ذهب نقي صنعها وجميع أوانيها.","37:25":"وصنع مذبح البخور من خشب السنط, طوله ذراع, وعرضه ذراع, مربعا. وارتفاعه ذراعان. منه كانت قرونه.","37:26":"وغشاه بذهب نقي: سطحه وحيطانه حواليه وقرونه. وصنع له إكليلا من ذهب حواليه.","37:27":"وصنع له حلقتين من ذهب تحت إكليله على جانبيه, على الجانبين بيتين لعصوين لحمله بهما.","37:28":"وصنع العصوين من خشب السنط وغشاهما بذهب.","37:29":"وصنع دهن المسحة مقدسا, والبخور العطر نقيا صنعة العطار.","38:1":"وصنع مذبح المحرقة من خشب السنط, طوله خمس أذرع, وعرضه خمس أذرع, مربعا. وارتفاعه ثلاث أذرع.","38:2":"وصنع قرونه على زواياه الأربع. منه كانت قرونه. وغشاه بنحاس.","38:3":"وصنع جميع آنية المذبح: القدور والرفوش والمراكن والمناشل والمجامر, جميع آنيته صنعها من نحاس.","38:4":"وصنع للمذبح شباكة صنعة الشبكة من نحاس, تحت حاجبه من أسفل إلى نصفه.","38:5":"وسبك أربع حلقات في الأربعة الأطراف لشباكة النحاس بيوتا للعصوين.","38:6":"وصنع العصوين من خشب السنط وغشاهما بنحاس.","38:7":"وأدخل العصوين في الحلقات على جانبي المذبح لحمله بهما. مجوفا صنعه من ألواح.","38:8":"وصنع المرحضة من نحاس وقاعدتها من نحاس. من مرائي المتجندات اللواتي تجندن عند باب خيمة الاجتماع.","38:9":"وصنع الدار: إلى جهة الجنوب نحو التيمن, أستار الدار من بوص مبروم مئة ذراع,","38:10":"أعمدتها عشرون, وقواعدها عشرون من نحاس. رزز الأعمدة وقضبانها من فضة.","38:11":"وإلى جهة الشمال, مئة ذراع, أعمدتها عشرون وقواعدها عشرون من نحاس. رزز الأعمدة وقضبانها من فضة.","38:12":"وإلى جهة الغرب أستار, خمسون ذراعا, أعمدتها عشرة وقواعدها عشر. رزز الأعمدة وقضبانها من فضة.","38:13":"وإلى جهة الشرق نحو الشروق, خمسون ذراعا.","38:14":"للجانب الواحد أستار خمس عشرة ذراعا, أعمدتها ثلاثة وقواعدها ثلاث.","38:15":"وللجانب الثاني من باب الدار إلى هنا وإلى هنا أستار خمس عشرة ذراعا, أعمدتها ثلاثة وقواعدها ثلاث.","38:16":"جميع أستار الدار حواليها من بوص مبروم,","38:17":"وقواعد الأعمدة من نحاس. رزز الأعمدة وقضبانها من فضة وتغشية رؤوسها من فضة وجميع أعمدة الدار موصولة بقضبان من فضة.","38:18":"وسجف باب الدار صنعة الطراز من أسمانجوني وأرجوان وقرمز وبوص مبروم, وطوله عشرون ذراعا, وارتفاعه بالعرض خمس أذرع بسوية أستار الدار,","38:19":"وأعمدتها أربعة, وقواعدها أربع من نحاس. رززها من فضة, وتغشية رؤوسها وقضبانها من فضة.","38:20":"وجميع أوتاد المسكن والدار حواليها من نحاس.","38:21":"هذا هو المحسوب للمسكن, مسكن الشهادة الذي حسب بموجب أمر موسى بخدمة اللاويين على يد إيثامار بن هارون الكاهن.","38:22":"وبصلئيل بن أوري بن حور من سبط يهوذا صنع كل ما أمر به الرب موسى.","38:23":"ومعه أهوليآب بن أخيساماك من سبط دان, نقاش وموش وطراز بالأسمانجوني والأرجوان والقرمز والبوص.","38:24":"كل الذهب المصنوع للعمل في جميع عمل المقدس, وهو ذهب التقدمة: تسع وعشرون وزنة وسبع مئة شاقل وثلاثون شاقلا بشاقل المقدس.","38:25":"وفضة المعدودين من الجماعة مئة وزنة وألف وسبع مئة شاقل وخمسة وسبعون شاقلا بشاقل المقدس.","38:26":"للرأس نصف, نصف الشاقل بشاقل المقدس. لكل من اجتاز إلى المعدودين من ابن عشرين سنة فصاعدا, لست مئة ألف وثلاثة آلاف وخمس مئة وخمسين.","38:27":"وكانت مئة وزنة من الفضة لسبك قواعد المقدس وقواعد الحجاب. مئة قاعدة للمئة وزنة. وزنة للقاعدة.","38:28":"والألف والسبع مئة شاقل والخمسة والسبعون شاقلا صنع منها رززا للأعمدة وغشى رؤوسها ووصلها بقضبان.","38:29":"ونحاس التقدمة سبعون وزنة وألفان وأربع مئة شاقل.","38:30":"ومنه صنع قواعد باب خيمة الاجتماع ومذبح النحاس وشباكة النحاس التي له وجميع آنية المذبح","38:31":"وقواعد الدار حواليها وقواعد باب الدار وجميع أوتاد المسكن وجميع أوتاد الدار حواليها.","39:1":"ومن الأسمانجوني والأرجوان والقرمز صنعوا ثيابا منسوجة للخدمة في المقدس, وصنعوا الثياب المقدسة التي لهارون, كما أمر الرب موسى.","39:2":"فصنع الرداء من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم.","39:3":"ومدوا الذهب صفائح وقدوها خيوطا ليصنعوها في وسط الأسمانجوني والأرجوان والقرمز والبوص, صنعة الموشي.","39:4":"وصنعوا له كتفين موصولين. على طرفيه اتصل.","39:5":"وزنار شده الذي عليه كان منه كصنعته من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم, كما أمر الرب موسى.","39:6":"وصنعوا حجري الجزع محاطين بطوقين من ذهب منقوشين نقش الخاتم على حسب أسماء بني إسرائيل.","39:7":"ووضعهما على كتفي الرداء حجري تذكار لبني إسرائيل, كما أمر الرب موسى.","39:8":"وصنع الصدرة صنعة الموشي كصنعة الرداء من ذهب وأسمانجوني وأرجوان وقرمز وبوص مبروم.","39:9":"كانت مربعة. مثنية صنعوا الصدرة. طولها شبر وعرضها شبر مثنية.","39:10":"ورصعوا فيها أربعة صفوف حجارة. صف: عقيق أحمر وياقوت أصفر وزمرد, الصف الأول.","39:11":"والصف الثاني: بهرمان وياقوت أزرق وعقيق أبيض.","39:12":"والصف الثالث: عين الهر ويشم وجمست.","39:13":"والصف الرابع: زبرجد وجزع ويشب. محاطة بأطواق من ذهب في ترصيعها.","39:14":"والحجارة كانت على أسماء بني إسرائيل, اثني عشر على أسمائهم كنقش الخاتم. كل واحد على اسمه للاثني عشر سبطا.","39:15":"وصنعوا على الصدرة سلاسل مجدولة صنعة الضفر من ذهب نقي.","39:16":"وصنعوا طوقين من ذهب وحلقتين من ذهب, وجعلوا الحلقتين على طرفي الصدرة.","39:17":"وجعلوا ضفيرتي الذهب في الحلقتين على طرفي الصدرة.","39:18":"وطرفا الضفيرتين جعلوهما في الطوقين, وجعلوهما على كتفي الرداء إلى قدامه.","39:19":"وصنعوا حلقتين من ذهب ووضعوهما على طرفي الصدرة. على حاشيتها التي إلى جهة الرداء من داخل.","39:20":"وصنعوا حلقتين من ذهب وجعلوهما على كتفي الرداء من أسفل من قدامه عند وصله فوق زنار الرداء.","39:21":"وربطوا الصدرة بحلقتيها إلى حلقتي الرداء بخيط من أسمانجوني ليكون على زنار الرداء, ولا تنزع الصدرة عن الرداء, كما أمر الرب موسى.","39:22":"وصنع جبة الرداء صنعة النساج, كلها من أسمانجوني.","39:23":"وفتحة الجبة في وسطها كفتحة الدرع, ولفتحتها حاشية حواليها. لا تنشق.","39:24":"وصنعوا على أذيال الجبة رمانات من أسمانجوني وأرجوان وقرمز مبروم.","39:25":"وصنعوا جلاجل من ذهب نقي, وجعلوا الجلاجل في وسط الرمانات على أذيال الجبة حواليها في وسط الرمانات.","39:26":"جلجل ورمانة. جلجل ورمانة. على أذيال الجبة حواليها للخدمة, كما أمر الرب موسى.","39:27":"وصنعوا الأقمصة من بوص صنعة النساج لهارون وبنيه.","39:28":"والعمامة من بوص, وعصائب القلانس من بوص, وسراويل الكتان من بوص مبروم.","39:29":"والمنطقة من بوص مبروم وأسمانجوني وأرجوان وقرمز صنعة الطراز, كما أمر الرب موسى.","39:30":"وصنعوا صفيحة الإكليل المقدس من ذهب نقي, وكتبوا عليها كتابة نقش الخاتم: «قدس للرب».","39:31":"وجعلوا عليها خيط أسمانجوني لتجعل على العمامة من فوق, كما أمر الرب موسى.","39:32":"فكمل كل عمل مسكن خيمة الاجتماع. وصنع بنو إسرائيل بحسب كل ما أمر الرب موسى. هكذا صنعوا.","39:33":"وجاءوا إلى موسى بالمسكن: الخيمة وجميع أوانيها, أشظتها وألواحها وعوارضها وأعمدتها وقواعدها,","39:34":"والغطاء من جلود الكباش المحمرة, والغطاء من جلود التخس, وحجاب السجف,","39:35":"وتابوت الشهادة وعصويه, والغطاء,","39:36":"والمائدة وكل آنيتها, وخبز الوجوه,","39:37":"والمنارة الطاهرة وسرجها: السرج للترتيب, وكل آنيتها والزيت للضوء,","39:38":"ومذبح الذهب, ودهن المسحة, والبخور العطر, والسجف لمدخل الخيمة,","39:39":"ومذبح النحاس, وشباكة النحاس التي له وعصويه وكل آنيته, والمرحضة وقاعدتها,","39:40":"وأستار الدار وأعمدتها وقواعدها, والسجف لباب الدار وأطنابها وأوتادها, وجميع أواني خدمة المسكن لخيمة الاجتماع,","39:41":"والثياب المنسوجة للخدمة في المقدس, والثياب المقدسة لهارون الكاهن وثياب بنيه للكهانة.","39:42":"بحسب كل ما أمر الرب موسى هكذا صنع بنو إسرائيل كل العمل.","39:43":"فنظر موسى جميع العمل, وإذا هم قد صنعوه كما أمر الرب. هكذا صنعوا. فباركهم موسى.","40:1":"وكلم الرب موسى قائلا:","40:2":"«في الشهر الأول, في اليوم الأول من الشهر, تقيم مسكن خيمة الاجتماع,","40:3":"وتضع فيه تابوت الشهادة. وتستر التابوت بالحجاب.","40:4":"وتدخل المائدة وترتب ترتيبها. وتدخل المنارة وتصعد سرجها.","40:5":"وتجعل مذبح الذهب للبخور أمام تابوت الشهادة. وتضع سجف الباب للمسكن.","40:6":"وتجعل مذبح المحرقة قدام باب مسكن خيمة الاجتماع.","40:7":"وتجعل المرحضة بين خيمة الاجتماع والمذبح, وتجعل فيها ماء.","40:8":"وتضع الدار حولهن, وتجعل السجف لباب الدار.","40:9":"وتأخذ دهن المسحة وتمسح المسكن وكل ما فيه, وتقدسه وكل آنيته ليكون مقدسا.","40:10":"وتمسح مذبح المحرقة وكل آنيته, وتقدس المذبح ليكون المذبح قدس أقداس.","40:11":"وتمسح المرحضة وقاعدتها وتقدسها.","40:12":"وتقدم هارون وبنيه إلى باب خيمة الاجتماع وتغسلهم بماء.","40:13":"وتلبس هارون الثياب المقدسة وتمسحه وتقدسه ليكهن لي.","40:14":"وتقدم بنيه وتلبسهم أقمصة.","40:15":"وتمسحهم كما مسحت أباهم ليكهنوا لي. ويكون ذلك لتصير لهم مسحتهم كهنوتا أبديا في أجيالهم.","40:16":"ففعل موسى بحسب كل ما أمره الرب. هكذا فعل.","40:17":"وكان في الشهر الأول من السنة الثانية في أول الشهر أن المسكن أقيم.","40:18":"أقام موسى المسكن, وجعل قواعده ووضع ألواحه وجعل عوارضه وأقام أعمدته.","40:19":"وبسط الخيمة فوق المسكن, ووضع غطاء الخيمة عليها من فوق, كما أمر الرب موسى.","40:20":"وأخذ الشهادة وجعلها في التابوت, ووضع العصوين على التابوت, وجعل الغطاء على التابوت من فوق.","40:21":"وأدخل التابوت إلى المسكن, ووضع حجاب السجف وستر تابوت الشهادة, كما أمر الرب موسى.","40:22":"وجعل المائدة في خيمة الاجتماع في جانب المسكن نحو الشمال خارج الحجاب.","40:23":"ورتب عليها ترتيب الخبز أمام الرب, كما أمر الرب موسى.","40:24":"ووضع المنارة في خيمة الاجتماع مقابل المائدة في جانب المسكن نحو الجنوب.","40:25":"وأصعد السرج أمام الرب, كما أمر الرب موسى.","40:26":"ووضع مذبح الذهب في خيمة الاجتماع قدام الحجاب,","40:27":"وبخر عليه ببخور عطر, كما أمر الرب موسى.","40:28":"ووضع سجف الباب للمسكن.","40:29":"ووضع مذبح المحرقة عند باب مسكن خيمة الاجتماع, وأصعد عليه المحرقة والتقدمة, كما أمر الرب موسى.","40:30":"ووضع المرحضة بين خيمة الاجتماع والمذبح وجعل فيها ماء للاغتسال,","40:31":"ليغسل منها موسى وهارون وبنوه أيديهم وأرجلهم.","40:32":"عند دخولهم إلى خيمة الاجتماع وعند اقترابهم إلى المذبح يغسلون, كما أمر الرب موسى.","40:33":"وأقام الدار حول المسكن والمذبح ووضع سجف باب الدار. وأكمل موسى العمل.","40:34":"ثم غطت السحابة خيمة الاجتماع وملأ بهاء الرب المسكن.","40:35":"فلم يقدر موسى أن يدخل خيمة الاجتماع, لأن السحابة حلت عليها وبهاء الرب ملأ المسكن.","40:36":"وعند ارتفاع السحابة عن المسكن كان بنو إسرائيل يرتحلون في جميع رحلاتهم.","40:37":"وإن لم ترتفع السحابة لا يرتحلون إلى يوم ارتفاعها,","40:38":"لأن سحابة الرب كانت على المسكن نهارا. وكانت فيها نار ليلا أمام عيون كل بيت إسرائيل في جميع رحلاتهم."};
